'use client';

import React, { useState } from 'react';
import { Card, CardHeader, CardTitle, CardDescription, CardContent } from '@/components/ui/card';
import { Input } from '@/components/ui/input';
import { Button } from '@/components/ui/button';
import Link from 'next/link';

export default function ForgotPasswordPage() {
  const [identity, setIdentity] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [message, setMessage] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!identity.trim()) return;

    setIsLoading(true);
    setMessage(null);
    setError(null);

    try {
      const response = await fetch('/api/auth/forgot-password', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ identity: identity.trim() }),
      });

      const data = await response.json();

      if (!response.ok) {
        throw new Error(data.error || 'Ocurri├│ un error inesperado.');
      }

      setMessage(data.message);
    } catch (err: any) {
      setError(err.message);
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="min-h-screen flex items-center justify-center bg-slate-950 p-4">
      <Card className="w-full max-w-md border-slate-800 bg-slate-900 shadow-2xl animate-fade-in">
        <CardHeader className="text-center space-y-2">
          <div className="flex justify-center mb-1">
            <img src="/logo.png" alt="M&S Logo" className="h-16 w-auto object-contain" />
          </div>
          <CardTitle className="text-xl font-bold tracking-tight text-slate-100 mt-2">
            Recuperar Contrase├▒a
          </CardTitle>
          <CardDescription className="text-slate-400">
            Ingresa tu usuario o correo electr├│nico para recibir un enlace de restablecimiento
          </CardDescription>
        </CardHeader>
        <CardContent className="space-y-4">
          {message ? (
            <div className="space-y-4">
              <div className="p-4 bg-emerald-950/60 border border-emerald-800 text-emerald-300 text-xs font-semibold rounded-lg">
                Ô£ô {message}
              </div>
              <Link href="/login" className="block">
                <Button variant="secondary" className="w-full font-semibold py-2">
                  Volver al Login
                </Button>
              </Link>
            </div>
          ) : (
            <form onSubmit={handleSubmit} className="space-y-5">
              <Input
                label="Usuario o Email"
                name="identity"
                id="identity"
                placeholder="e.g. dmoyano o dmoyano@mstecnologia.com.ar"
                value={identity}
                onChange={(e) => setIdentity(e.target.value)}
                required
                autoFocus
              />

              {error && (
                <div className="p-3 bg-red-950/60 border border-red-800 text-red-300 text-xs font-semibold rounded-lg">
                  ÔÜá´©Å {error}
                </div>
              )}

              <div className="flex flex-col gap-2.5">
                <Button
                  type="submit"
                  className="w-full font-semibold py-2.5"
                  disabled={isLoading}
                >
                  {isLoading ? 'Enviando...' : 'Enviar Enlace de Recuperaci├│n'}
                </Button>

                <Link href="/login" className="text-center text-xs text-slate-450 hover:text-slate-300 transition-colors py-1">
                  Volver al inicio de sesi├│n
                </Link>
              </div>
            </form>
          )}
        </CardContent>
      </Card>
    </div>
  );
}

'use client';

import React, { useState } from 'react';
import { Card, CardHeader, CardTitle, CardDescription, CardContent } from '@/components/ui/card';
import { Input } from '@/components/ui/input';
import { Button } from '@/components/ui/button';

export default function LoginPage() {
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState<string | null>(null);
  const [isPending, setIsPending] = useState(false);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError(null);
    setIsPending(true);

    try {
      const response = await fetch('/api/auth/login', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({ username, password }),
      });

      const data = await response.json();

      if (!response.ok) {
        throw new Error(data.error || 'Usuario o contrase├▒a incorrectos.');
      }

      // Redirigir al dashboard tras persistir la cookie exitosamente en el navegador
      window.location.href = '/';
    } catch (err: any) {
      setError(err.message || 'Error de conexi├│n con el servidor.');
    } finally {
      setIsPending(false);
    }
  };

  return (
    <div className="min-h-screen flex items-center justify-center bg-slate-950 p-4">
      <Card className="w-full max-w-md border-slate-800 bg-slate-900 shadow-2xl animate-fade-in">
        <CardHeader className="text-center space-y-2">
          <div className="flex justify-center mb-1">
            <img src="/logo.png" alt="M&S Logo" className="h-16 w-auto object-contain" />
          </div>
          <CardTitle className="text-xl font-bold tracking-tight text-slate-100 mt-2">
            M&S Tecnolog├¡a Digital
          </CardTitle>
          <CardDescription className="text-slate-400">
            M&S Tecnolog├¡a Digital ÔÇö Sistema Administrativo
          </CardDescription>
        </CardHeader>
        <CardContent>
          <form onSubmit={handleSubmit} className="space-y-5">
            <Input
              label="Nombre de Usuario o Email"
              name="username"
              id="username"
              value={username}
              onChange={(e) => setUsername(e.target.value)}
              placeholder="e.g. dmoyano"
              required
              autoFocus
            />
            <Input
              label="Contrase├▒a"
              name="password"
              id="password"
              type="password"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              placeholder="ÔÇóÔÇóÔÇóÔÇóÔÇóÔÇóÔÇóÔÇó"
              required
            />

            {error && (
              <div className="p-3 bg-red-950/60 border border-red-800 text-red-300 text-xs font-semibold rounded-lg">
                ÔÜá´©Å {error}
              </div>
            )}

            <Button
              type="submit"
              className="w-full font-semibold py-2.5"
              disabled={isPending}
            >
              {isPending ? 'Iniciando Sesi├│n...' : 'Ingresar al Sistema'}
            </Button>
          </form>
        </CardContent>
      </Card>
    </div>
  );
}

'use client';

import React, { useState, Suspense } from 'react';
import { useSearchParams, useRouter } from 'next/navigation';
import { Card, CardHeader, CardTitle, CardDescription, CardContent } from '@/components/ui/card';
import { Input } from '@/components/ui/input';
import { Button } from '@/components/ui/button';
import Link from 'next/link';

function ResetPasswordForm() {
  const searchParams = useSearchParams();
  const token = searchParams.get('token') || '';
  const router = useRouter();

  const [password, setPassword] = useState('');
  const [confirmPassword, setConfirmPassword] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [message, setMessage] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    if (!token) {
      setError('Token de recuperaci├│n no v├ílido o ausente.');
      return;
    }
    if (password.length < 8) {
      setError('La contrase├▒a debe tener al menos 8 caracteres.');
      return;
    }
    if (password !== confirmPassword) {
      setError('Las contrase├▒as ingresadas no coinciden.');
      return;
    }

    setIsLoading(true);
    setMessage(null);
    setError(null);

    try {
      const response = await fetch('/api/auth/reset-password', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ token, password }),
      });

      const data = await response.json();

      if (!response.ok) {
        throw new Error(data.error || 'Ocurri├│ un error inesperado.');
      }

      setMessage(data.message);
    } catch (err: any) {
      setError(err.message);
    } finally {
      setIsLoading(false);
    }
  };

  if (!token) {
    return (
      <div className="space-y-4">
        <div className="p-3 bg-red-950/60 border border-red-800 text-red-300 text-xs font-semibold rounded-lg">
          ÔÜá´©Å El enlace de restablecimiento es inv├ílido o no contiene un token v├ílido.
        </div>
        <Link href="/forgot-password" className="block">
          <Button variant="secondary" className="w-full font-semibold py-2">
            Solicitar Nueva Recuperaci├│n
          </Button>
        </Link>
      </div>
    );
  }

  return (
    <CardContent className="space-y-4">
      {message ? (
        <div className="space-y-4">
          <div className="p-4 bg-emerald-950/60 border border-emerald-800 text-emerald-300 text-xs font-semibold rounded-lg">
            Ô£ô {message}
          </div>
          <Link href="/login" className="block">
            <Button className="w-full font-semibold py-2">
              Ingresar al Sistema
            </Button>
          </Link>
        </div>
      ) : (
        <form onSubmit={handleSubmit} className="space-y-5">
          <Input
            label="Nueva Contrase├▒a"
            name="password"
            id="password"
            type="password"
            placeholder="ÔÇóÔÇóÔÇóÔÇóÔÇóÔÇóÔÇóÔÇó"
            value={password}
            onChange={(e) => setPassword(e.target.value)}
            required
            autoFocus
          />

          <Input
            label="Confirmar Contrase├▒a"
            name="confirmPassword"
            id="confirmPassword"
            type="password"
            placeholder="ÔÇóÔÇóÔÇóÔÇóÔÇóÔÇóÔÇóÔÇó"
            value={confirmPassword}
            onChange={(e) => setConfirmPassword(e.target.value)}
            required
          />

          {error && (
            <div className="p-3 bg-red-950/60 border border-red-800 text-red-300 text-xs font-semibold rounded-lg">
              ÔÜá´©Å {error}
            </div>
          )}

          <Button
            type="submit"
            className="w-full font-semibold py-2.5"
            disabled={isLoading}
          >
            {isLoading ? 'Guardando...' : 'Guardar Nueva Contrase├▒a'}
          </Button>
        </form>
      )}
    </CardContent>
  );
}

export default function ResetPasswordPage() {
  return (
    <div className="min-h-screen flex items-center justify-center bg-slate-950 p-4">
      <Card className="w-full max-w-md border-slate-800 bg-slate-900 shadow-2xl animate-fade-in">
        <CardHeader className="text-center space-y-2">
          <div className="flex justify-center mb-1">
            <img src="/logo.png" alt="M&S Logo" className="h-16 w-auto object-contain" />
          </div>
          <CardTitle className="text-xl font-bold tracking-tight text-slate-100 mt-2">
            Restablecer Contrase├▒a
          </CardTitle>
          <CardDescription className="text-slate-400">
            Ingresa tu nueva contrase├▒a administrativa segura
          </CardDescription>
        </CardHeader>
        <Suspense fallback={<div className="text-center text-slate-400 p-6 text-xs animate-pulse">Cargando token de verificaci├│n...</div>}>
          <ResetPasswordForm />
        </Suspense>
      </Card>
    </div>
  );
}

'use client';

import React, { useState } from 'react';
import { useManagement } from '@/lib/context';
import { TableContainer, Table, TableHeader, TableRow, TableHeaderCell, TableBody, TableCell } from '@/components/ui/table';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Select } from '@/components/ui/select';
import { Modal } from '@/components/ui/modal';
import { Card, CardContent } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import { formatCurrency } from '@/lib/utils';
import { Plus, Trash2, Edit, FileText, CheckCircle, ShieldAlert, Sparkles } from 'lucide-react';
import { Abono } from '@/lib/mockData';

export default function AbonosPage() {
    const { abonos, setAbonos, machines, clients, rentals, updateAbonoAction } = useManagement();
    const [searchQuery, setSearchQuery] = useState('');
    const [filterActive, setFilterActive] = useState('');

    // Modal states
    const [isFormOpen, setIsFormOpen] = useState(false);
    const [isDetailOpen, setIsDetailOpen] = useState(false);
    const [editingAbono, setEditingAbono] = useState<Abono | null>(null);
    const [selectedAbono, setSelectedAbono] = useState<Abono | null>(null);
    const [formError, setFormError] = useState('');

    // Form inputs
    const [name, setName] = useState('');
    const [price, setPrice] = useState('0');
    const [limit, setLimit] = useState('2000');
    const [excessPrice, setExcessPrice] = useState('15.5');
    const [isActive, setIsActive] = useState(true);

    const handleOpenForm = (abono: Abono | null = null) => {
        setFormError('');
        if (abono) {
            setEditingAbono(abono);
            setName(abono.name);
            setPrice(String(abono.price));
            setLimit(String(abono.limit));
            setExcessPrice(String(abono.excessPrice));
            setIsActive(abono.active !== false);
        } else {
            setEditingAbono(null);
            setName('');
            setPrice('0');
            setLimit('2000');
            setExcessPrice('15.5');
            setIsActive(true);
        }
        setIsFormOpen(true);
    };

    const handleSaveAbono = (e: React.FormEvent) => {
        e.preventDefault();
        setFormError('');

        if (!name.trim()) {
            setFormError('El nombre del plan es obligatorio.');
            return;
        }

        // Duplicate Check
        const cleanName = name.trim().toLowerCase();
        const duplicate = abonos.find(a => 
            a.name.trim().toLowerCase() === cleanName && 
            (!editingAbono || a.id !== editingAbono.id)
        );

        if (duplicate) {
            setFormError(`El nombre de plan "${name}" ya existe.`);
            return;
        }

        const abonoData: Abono = {
            id: editingAbono ? editingAbono.id : 'abono-' + Date.now(),
            name,
            price: parseFloat(price) || 0,
            limit: parseInt(limit, 10) || 0,
            excessPrice: parseFloat(excessPrice) || 0,
            active: isActive
        };

        if (editingAbono) {
            updateAbonoAction(abonoData, 'update');
        } else {
            updateAbonoAction(abonoData, 'create');
        }

        setIsFormOpen(false);
    };

    const handleDeleteAbono = (id: string) => {
        const activeRentals = machines.filter(m => m.abonoId === id).length;
        if (activeRentals > 0) {
            alert(`No se puede eliminar el plan porque hay ${activeRentals} m├íquina(s) us├índolo actualmente. Considere desactivarlo para evitar nuevos alquileres.`);
            return;
        }

        if (confirm('┬┐Est├í seguro de que desea eliminar este plan de abono del cat├ílogo?')) {
            updateAbonoAction({ id } as any, 'delete');
        }
    };

    const handleOpenDetail = (abono: Abono) => {
        setSelectedAbono(abono);
        setIsDetailOpen(true);
    };

    const filteredAbonos = abonos.filter(a => {
        const matchesSearch = a.name.toLowerCase().includes(searchQuery.toLowerCase());
        const isPlanActive = a.active !== false;

        let matchesStatus = true;
        if (filterActive === 'active') {
            matchesStatus = isPlanActive;
        } else if (filterActive === 'inactive') {
            matchesStatus = !isPlanActive;
        }

        return matchesSearch && matchesStatus;
    });

    return (
        <div className="space-y-6 animate-fade-in text-slate-100 pb-12">

            {/* Action Bar */}
            <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
                <div className="flex flex-1 gap-3 max-w-lg">
                    {/* B├║squeda */}
                    <input
                        type="text"
                        value={searchQuery}
                        onChange={(e) => setSearchQuery(e.target.value)}
                        placeholder="Buscar plan de abono por nombre..."
                        className="w-full bg-slate-900 border border-slate-800 rounded-xl px-4 py-2 text-xs text-slate-100 placeholder-slate-500 outline-none focus:ring-1 focus:ring-indigo-500"
                    />

                    {/* Status filter */}
                    <select
                        value={filterActive}
                        onChange={(e) => setFilterActive(e.target.value)}
                        className="bg-slate-900 border border-slate-800 rounded-xl px-3 py-2 text-slate-300 text-xs focus:outline-none"
                    >
                        <option value="">Estado: Todos</option>
                        <option value="active">Solo Activos</option>
                        <option value="inactive">Solo Inactivos</option>
                    </select>
                </div>
                <Button variant="primary" size="sm" onClick={() => handleOpenForm()}>
                    <Plus size={16} className="mr-1.5" /> Crear Plan
                </Button>
            </div>

            {/* List Table */}
            <TableContainer>
                <Table>
                    <TableHeader>
                        <TableRow>
                            <TableHeaderCell>ID Plan</TableHeaderCell>
                            <TableHeaderCell>Nombre del Plan</TableHeaderCell>
                            <TableHeaderCell>Abono Base Mensual</TableHeaderCell>
                            <TableHeaderCell>Copias Incluidas</TableHeaderCell>
                            <TableHeaderCell>Copia Excedente</TableHeaderCell>
                            <TableHeaderCell>Alquileres Activos</TableHeaderCell>
                            <TableHeaderCell>Estado</TableHeaderCell>
                            <TableHeaderCell className="text-right">Acciones</TableHeaderCell>
                        </TableRow>
                    </TableHeader>
                    <TableBody>
                        {filteredAbonos.length === 0 ? (
                            <TableRow>
                                <TableCell colSpan={8} className="text-center py-10 text-slate-500 text-xs italic">
                                    No se encontraron planes de abonos registrados.
                                </TableCell>
                            </TableRow>
                        ) : (
                            filteredAbonos.map(a => {
                                const activeRentals = machines.filter(m => m.abonoId === a.id).length;
                                const isPlanActive = a.active !== false;

                                return (
                                    <TableRow key={a.id} className="hover:bg-slate-900/40">
                                        <TableCell className="text-xs font-mono-tabular font-bold text-slate-550">{a.id}</TableCell>
                                        <TableCell className="font-bold text-slate-100">{a.name}</TableCell>
                                        <TableCell className="font-mono-tabular text-xs text-slate-300">{formatCurrency(a.price)}</TableCell>
                                        <TableCell className="font-mono-tabular text-xs text-slate-300">{a.limit.toLocaleString('es-AR')} copias</TableCell>
                                        <TableCell className="font-mono-tabular text-xs font-semibold text-slate-300">{formatCurrency(a.excessPrice)}</TableCell>
                                        <TableCell className="text-xs font-semibold text-slate-350 font-mono-tabular">
                                            {activeRentals > 0 ? `${activeRentals} m├íquina(s)` : <span className="text-slate-500 italic">Sin uso</span>}
                                        </TableCell>
                                        <TableCell className="text-xs">
                                            <span className={`px-2 py-0.5 rounded text-[10px] font-extrabold uppercase ${
                                                isPlanActive ? 'bg-emerald-500/10 text-emerald-400 border border-emerald-500/20' : 'bg-red-500/10 text-red-400 border border-red-500/20'
                                            }`}>
                                                {isPlanActive ? 'VIGENTE' : 'DESACTIVADO'}
                                            </span>
                                        </TableCell>
                                        <TableCell className="text-right">
                                            <div className="flex justify-end gap-1.5">
                                                <button 
                                                    title="Ficha del Abono"
                                                    onClick={() => handleOpenDetail(a)}
                                                    className="p-1.5 bg-slate-900 border border-slate-800 rounded-lg hover:bg-slate-850 transition-colors"
                                                >
                                                    <FileText size={13} className="text-indigo-400" />
                                                </button>
                                                <button 
                                                    title="Editar Plan"
                                                    onClick={() => handleOpenForm(a)}
                                                    className="p-1.5 bg-slate-900 border border-slate-800 rounded-lg hover:bg-slate-850 transition-colors"
                                                >
                                                    <Edit size={13} className="text-slate-400" />
                                                </button>
                                                <button 
                                                    title="Eliminar Plan"
                                                    onClick={() => handleDeleteAbono(a.id)}
                                                    className="p-1.5 bg-red-955/20 border border-red-900/30 rounded-lg hover:bg-red-900/20 transition-colors"
                                                >
                                                    <Trash2 size={13} className="text-red-400" />
                                                </button>
                                            </div>
                                        </TableCell>
                                    </TableRow>
                                );
                            })
                        )}
                    </TableBody>
                </Table>
            </TableContainer>

            {/* Modal: Formulario Plan */}
            <Modal
                isOpen={isFormOpen}
                onClose={() => setIsFormOpen(false)}
                title={editingAbono ? 'Editar Plan de Abono' : 'Crear Plan de Abono'}
                footer={
                    <div className="flex gap-2">
                        <Button variant="ghost" size="sm" onClick={() => setIsFormOpen(false)}>
                            Cancelar
                        </Button>
                        <Button variant="primary" size="sm" onClick={handleSaveAbono}>
                            Guardar Plan
                        </Button>
                    </div>
                }
            >
                <form className="space-y-4 animate-fade-in" onSubmit={handleSaveAbono}>
                    <Input
                        label="Nombre del Plan *"
                        value={name}
                        onChange={(e) => setName(e.target.value)}
                        required
                        placeholder="Ej: Plan B├ísico 2000"
                    />
                    <Input
                        label="Precio de Abono Base ($) *"
                        type="number"
                        value={price}
                        onChange={(e) => setPrice(e.target.value)}
                        required
                    />
                    <div className="grid grid-cols-2 gap-4">
                        <Input
                            label="Copias Incluidas *"
                            type="number"
                            value={limit}
                            onChange={(e) => setLimit(e.target.value)}
                            required
                        />
                        <Input
                            label="Precio por Copia Excedente ($) *"
                            type="number"
                            value={excessPrice}
                            onChange={(e) => setExcessPrice(e.target.value)}
                            required
                        />
                    </div>

                    <Select
                        label="Estado de Comercializaci├│n"
                        value={isActive ? 'true' : 'false'}
                        onChange={(e) => setIsActive(e.target.value === 'true')}
                        options={[
                            { value: 'true', label: 'VIGENTE (Disponible para nuevos contratos)' },
                            { value: 'false', label: 'DESACTIVADO (Solo para contratos hist├│ricos)' }
                        ]}
                    />

                    {formError && (
                        <p className="text-red-500 text-[10px] font-bold mt-1 bg-red-500/10 p-2.5 rounded-lg border border-red-500/20">{formError}</p>
                    )}
                </form>
            </Modal>

            {/* Modal: Ficha Detallada de Abono */}
            <Modal
                isOpen={isDetailOpen}
                onClose={() => setIsDetailOpen(false)}
                title="Ficha del Plan de Abono"
                footer={
                    <Button variant="secondary" size="sm" onClick={() => setIsDetailOpen(false)}>
                        Cerrar Ficha
                    </Button>
                }
            >
                {selectedAbono && (
                    <div className="space-y-5">

                        {/* Header */}
                        <div className="border-b border-slate-850 pb-4 flex justify-between items-center">
                            <div>
                                <h4 className="text-base font-extrabold text-slate-100">{selectedAbono.name}</h4>
                                <span className="text-xs text-slate-400 block mt-1">ID: {selectedAbono.id}</span>
                            </div>
                            <span className={`px-2 py-0.5 rounded text-[9px] font-extrabold uppercase ${
                                selectedAbono.active !== false ? 'bg-emerald-500/10 text-emerald-455' : 'bg-red-500/10 text-red-455'
                            }`}>
                                {selectedAbono.active !== false ? 'VIGENTE' : 'DESACTIVADO'}
                            </span>
                        </div>

