                                                <TableCell className="font-mono-tabular">{formatCurrency(item.precioUnitario)}</TableCell>
                                                <TableCell className="font-mono-tabular text-right">{formatCurrency(item.subtotal)}</TableCell>
                                            </TableRow>
                                        ))}
                                    </TableBody>
                                </Table>
                            </TableContainer>
                        )}

                        {/* Financial Breakdown */}
                        <div className="pt-4 flex flex-col items-end space-y-1 text-xs">
                            <div className="flex justify-between w-64">
                                <span>Subtotal:</span>
                                <span className="font-mono-tabular">{formatCurrency(selectedBudget.subtotal)}</span>
                            </div>
                            {selectedBudget.discountAmount > 0 && (
                                <div className="flex justify-between w-64 text-red-650">
                                    <span>Descuento:</span>
                                    <span className="font-mono-tabular">-{formatCurrency(selectedBudget.discountAmount)}</span>
                                </div>
                            )}
                            {selectedBudget.ivaMode === 'ADD_21' && (
                                <div className="flex justify-between w-64 border-t pt-1">
                                    <span>IVA (21%):</span>
                                    <span className="font-mono-tabular">{formatCurrency(selectedBudget.ivaAmount)}</span>
                                </div>
                            )}
                            <div className="flex justify-between w-64 font-bold text-sm border-t pt-2">
                                <span>Total General:</span>
                                <span className="font-mono-tabular">{formatCurrency(selectedBudget.total)}</span>
                            </div>
                            
                            <span className="text-[9px] text-slate-500 italic mt-1 block">
                                {selectedBudget.ivaMode === 'INCLUDED' && 'Los precios indicados incluyen IVA.'}
                                {selectedBudget.ivaMode === 'PLUS_IVA' && 'Los precios indicados no incluyen IVA (Precios + IVA).'}
                                {selectedBudget.ivaMode === 'EXEMPT' && 'Operaci├│n exenta de IVA.'}
                            </span>
                        </div>

                        {/* Commercial Terms block */}
                        <div className="border-t pt-4 grid grid-cols-2 gap-4 text-[10px]">
                            <div className="space-y-1">
                                <span className="font-bold block uppercase text-[8px] tracking-wider">Condiciones Comerciales</span>
                                <p>Validez de la oferta: <strong>{selectedBudget.validezOferta}</strong></p>
                                {selectedBudget.tipo === 'alquiler' && (
                                    <>
                                        <p>Plazo m├¡nimo de contrato: <strong>{selectedBudget.plazoMinimoContrato}</strong></p>
                                        <p>Ajuste de precio: <strong>{selectedBudget.ajustePrecios}</strong></p>
                                    </>
                                )}
                                {selectedBudget.conditionsText && (
                                    <p className="text-[9px] text-slate-550 pt-1.5 leading-normal">{selectedBudget.conditionsText}</p>
                                )}
                            </div>
                            <div className="space-y-1">
                                <span className="font-bold block uppercase text-[8px] tracking-wider">Servicios y Soporte Incluidos</span>
                                {selectedBudget.includesText && (
                                    <p className="text-[9px] leading-relaxed">{selectedBudget.includesText}</p>
                                )}
                            </div>
                        </div>

                        {/* Requirements for non-state client */}
                        {selectedBudget.requirementsText && (
                            <div className="border-t pt-4 text-[9px] text-slate-500">
                                <span className="font-bold block uppercase text-[8px] tracking-wider mb-1">Requisitos de Contrataci├│n</span>
                                <p className="leading-relaxed">{selectedBudget.requirementsText}</p>
                            </div>
                        )}

                        <div className="flex justify-between pt-16 text-[10px]">
                            <div className="border-t w-52 text-center pt-2">Firma y Aclaraci├│n M&S</div>
                            <div className="border-t w-52 text-center pt-2">Firma y Aclaraci├│n Cliente</div>
                        </div>

                        <div className="text-center pt-12 text-[9px] text-slate-400 border-t">
                            {selectedBudget.footerText}
                        </div>
                    </div>
                </div>
            )}

            {/* Modal: Share Email */}
            <Modal
                isOpen={isEmailModalOpen}
                onClose={() => setIsEmailModalOpen(false)}
                title="Compartir Propuesta por Email"
                footer={
                    <>
                        <Button variant="ghost" size="sm" onClick={() => setIsEmailModalOpen(false)}>
                            Cancelar
                        </Button>
                        <Button variant="primary" size="sm" onClick={handleSendEmail}>
                            Enviar Email
                        </Button>
                    </>
                }
            >
                <form className="space-y-4 text-xs" onSubmit={handleSendEmail}>
                    <Input
                        label="Correo del Destinatario *"
                        type="email"
                        value={shareEmail}
                        onChange={(e) => setShareEmail(e.target.value)}
                        required
                    />
                    <Input
                        label="Asunto *"
                        value={shareSubject}
                        onChange={(e) => setShareSubject(e.target.value)}
                        required
                    />
                    <div>
                        <label className="text-[10px] uppercase font-bold text-slate-500 block mb-1">Mensaje Adjunto</label>
                        <textarea
                            value={shareMessage}
                            onChange={(e) => setShareMessage(e.target.value)}
                            className="w-full bg-slate-900 border border-slate-800 rounded-xl px-3 py-2 text-slate-200 h-24 resize-none"
                            required
                        />
                    </div>
                    <span className="text-[10px] text-slate-500 italic block">Ôä╣´©Å Se adjuntar├í autom├íticamente una versi├│n digital de la propuesta en formato PDF.</span>
                </form>
            </Modal>

            {/* Modal: Share WhatsApp */}
            <Modal
                isOpen={isWhatsappModalOpen}
                onClose={() => setIsWhatsappModalOpen(false)}
                title="Enviar Enlace de WhatsApp"
                footer={
                    <>
                        <Button variant="ghost" size="sm" onClick={() => setIsWhatsappModalOpen(false)}>
                            Cancelar
                        </Button>
                        <Button variant="primary" size="sm" className="bg-emerald-600 hover:bg-emerald-555 text-white" onClick={handleSendWhatsapp}>
                            Continuar a WhatsApp
                        </Button>
                    </>
                }
            >
                <form className="space-y-4 text-xs" onSubmit={handleSendWhatsapp}>
                    <Input
                        label="N├║mero de WhatsApp (Con c├│digo de ├írea, ej: 5491155551234) *"
                        value={sharePhone}
                        onChange={(e) => setSharePhone(e.target.value)}
                        required
                    />
                    <div>
                        <label className="text-[10px] uppercase font-bold text-slate-500 block mb-1">Mensaje Editable</label>
                        <textarea
                            value={shareMessage}
                            onChange={(e) => setShareMessage(e.target.value)}
                            className="w-full bg-slate-900 border border-slate-800 rounded-xl px-3 py-2 text-slate-200 h-32 resize-none"
                            required
                        />
                    </div>
                </form>
            </Modal>

            {/* Modal: Preset Form (Catalog) */}
            <Modal
                isOpen={isPresetModalOpen}
                onClose={() => setIsPresetModalOpen(false)}
                title={editingPreset ? 'Editar Preset de M├íquina' : 'Registrar Nuevo Preset de M├íquina'}
                footer={
                    <>
                        <Button variant="ghost" size="sm" onClick={() => setIsPresetModalOpen(false)}>
                            Cancelar
                        </Button>
                        <Button variant="primary" size="sm" onClick={handleSavePreset}>
                            Guardar Preset
                        </Button>
                    </>
                }
            >
                <form className="space-y-4 text-xs" onSubmit={handleSavePreset}>
                    <div className="grid grid-cols-2 gap-4">
                        <Input
                            label="Marca *"
                            value={presetMarca}
                            onChange={(e) => setPresetMarca(e.target.value)}
                            required
                            placeholder="HP, Brother, Ricoh"
                        />
                        <Input
                            label="Modelo *"
                            value={presetModelo}
                            onChange={(e) => setPresetModelo(e.target.value)}
                            required
                            placeholder="Ej: IM 430F"
                        />
                    </div>
                    <Input
                        label="Nombre Comercial"
                        value={presetNombre}
                        onChange={(e) => setPresetNombre(e.target.value)}
                        placeholder="Ej: Ricoh IM 430F Corporativo"
                    />
                    <div className="grid grid-cols-2 gap-4">
                        <Select
                            label="Tipo de Copiado"
                            value={presetTipo}
                            onChange={(e) => setPresetTipo(e.target.value)}
                            options={[
                                { value: 'Monocrom├ítica (B&N)', label: 'Monocrom├ítica (B&N)' },
                                { value: 'Color', label: 'Color' }
                            ]}
                        />
                        <Input
                            label="Velocidad (PPM) *"
                            type="number"
                            value={presetPpm}
                            onChange={(e) => setPresetPpm(e.target.value)}
                            required
                        />
                    </div>
                    <div>
                        <label className="text-[10px] uppercase font-bold text-slate-500 block mb-1">Especificaciones T├®cnicas resumidas *</label>
                        <textarea
                            value={presetSpecs}
                            onChange={(e) => setPresetSpecs(e.target.value)}
                            className="w-full bg-slate-900 border border-slate-800 rounded-xl px-3 py-2 text-slate-200 h-20 resize-none"
                            required
                            placeholder="Resoluci├│n, duplex, capacidad de papel..."
                        />
                    </div>
                    <div>
                        <label className="text-[10px] uppercase font-bold text-slate-500 block mb-1">Notas Comerciales</label>
                        <textarea
                            value={presetNotes}
                            onChange={(e) => setPresetNotes(e.target.value)}
                            className="w-full bg-slate-900 border border-slate-800 rounded-xl px-3 py-2 text-slate-200 h-16 resize-none"
                            placeholder="Recomendaciones comerciales..."
                        />
                    </div>
                </form>
            </Modal>

            {/* Modal: Template Form (Catalog) */}
            <Modal
                isOpen={isTemplateModalOpen}
                onClose={() => setIsTemplateModalOpen(false)}
                title={editingTemplate ? 'Editar Plantilla de Textos' : 'Nueva Plantilla de Textos'}
                footer={
                    <>
                        <Button variant="ghost" size="sm" onClick={() => setIsTemplateModalOpen(false)}>
                            Cancelar
                        </Button>
                        <Button variant="primary" size="sm" onClick={handleSaveTemplate}>
                            Guardar Plantilla
                        </Button>
                    </>
                }
            >
                <form className="space-y-4 text-xs" onSubmit={handleSaveTemplate}>
                    <Input
                        label="Nombre de la Plantilla *"
                        value={tempNombre}
                        onChange={(e) => setTempNombre(e.target.value)}
                        required
                        placeholder="Ej: Alquiler Corporativo"
                    />
                    <Select
                        label="Tipo de Propuesta Asociado"
                        value={tempTipo}
                        onChange={(e) => setTempTipo(e.target.value as any)}
                        options={[
                            { value: 'alquiler', label: 'Alquiler de Copiadoras' },
                            { value: 'insumo', label: 'Insumos / Consumibles' },
                            { value: 'repuesto', label: 'Venta de Repuestos' },
                            { value: 'servicio_tecnico', label: 'Servicio T├®cnico' },
                            { value: 'mixto', label: 'Mixto' }
                        ]}
                    />
                    <div>
                        <label className="text-[10px] uppercase font-bold text-slate-500 block mb-1">Texto Introductorio de Propuesta *</label>
                        <textarea
                            value={tempIntro}
                            onChange={(e) => setTempIntro(e.target.value)}
                            className="w-full bg-slate-900 border border-slate-800 rounded-xl px-3 py-2 text-slate-200 h-16 resize-none"
                            required
                        />
                    </div>
                    <div>
                        <label className="text-[10px] uppercase font-bold text-slate-500 block mb-1">Cl├íusulas / Condiciones de Vencimiento</label>
                        <textarea
                            value={tempConditions}
                            onChange={(e) => setTempConditions(e.target.value)}
                            className="w-full bg-slate-900 border border-slate-800 rounded-xl px-3 py-2 text-slate-200 h-16 resize-none"
                        />
                    </div>
                    <div>
                        <label className="text-[10px] uppercase font-bold text-slate-500 block mb-1">Servicios Incluidos por defecto</label>
                        <textarea
                            value={tempIncludes}
                            onChange={(e) => setTempIncludes(e.target.value)}
                            className="w-full bg-slate-900 border border-slate-800 rounded-xl px-3 py-2 text-slate-200 h-16 resize-none"
                        />
                    </div>
                    <div>
                        <label className="text-[10px] uppercase font-bold text-slate-500 block mb-1">Conceptos Excluidos por defecto</label>
                        <textarea
                            value={tempExcludes}
                            onChange={(e) => setTempExcludes(e.target.value)}
                            className="w-full bg-slate-900 border border-slate-800 rounded-xl px-3 py-2 text-slate-200 h-16 resize-none"
                        />
                    </div>
                    <div>
                        <label className="text-[10px] uppercase font-bold text-slate-500 block mb-1">Requisitos de Contrataci├│n m├¡nimos</label>
                        <textarea
                            value={tempReqs}
                            onChange={(e) => setTempReqs(e.target.value)}
                            className="w-full bg-slate-900 border border-slate-800 rounded-xl px-3 py-2 text-slate-200 h-16 resize-none"
                        />
                    </div>
                </form>
            </Modal>
        </div>
    );
}

'use client';

import React, { useState, useEffect, useRef } from 'react';
import { useManagement } from '@/lib/context';
import { Card, CardContent } from '@/components/ui/card';
import { TableContainer, Table, TableHeader, TableRow, TableHeaderCell, TableBody, TableCell } from '@/components/ui/table';
import { Button } from '@/components/ui/button';
import { 
    Download, Upload, ShieldCheck, Database, FileSpreadsheet, 
    Trash2, AlertTriangle, Play, CheckCircle2, History, Filter, 
    Search, RefreshCw, AlertCircle, Wrench, RefreshCcw
} from 'lucide-react';
import { getAuditLogsAction, addAuditLogAction } from '@/app/actions/audit';
import { diagnoseDataAction, logCleanupOperationAction, DiagnosedIssue } from '@/app/actions/cleanup';

export default function RespaldoPage() {
    const { 
        clients, setClients, 
        machines, setMachines, 
        readings, setReadings, 
        tickets, setTickets, 
        abonos, setAbonos, 
        users, setUsers, 
        rentals, setRentals,
        currentUser 
    } = useManagement();

    const [isAuthorized, setIsAuthorized] = useState<boolean | null>(null);
    const [isLoadingAuth, setIsLoadingAuth] = useState(true);

    useEffect(() => {
        async function checkAuth() {
            try {
                const res = await fetch('/api/auth/me');
                const data = await res.json();
                if (res.ok && data.authenticated && data.user.permissions.isMaster) {
                    setIsAuthorized(true);
                } else {
                    setIsAuthorized(false);
                }
            } catch (e) {
                setIsAuthorized(false);
            } finally {
                setIsLoadingAuth(false);
            }
        }
        checkAuth();
    }, []);

    // Sub-tab Navigation
    const [currentSubTab, setCurrentSubTab] = useState<'exportar' | 'importar' | 'backup' | 'limpieza' | 'auditoria'>('exportar');

    // -------------------------------------------------------------
    // EXPORT TAB STATE
    // -------------------------------------------------------------
    const [exportModule, setExportModule] = useState<'clientes' | 'maquinas' | 'alquileres' | 'abonos' | 'lecturas' | 'tickets'>('clientes');
    const [exportFormat, setExportFormat] = useState<'csv' | 'json'>('csv');
    const [exportStatusFilter, setExportStatusFilter] = useState('');
    const [isExporting, setIsExporting] = useState(false);

    // -------------------------------------------------------------
    // IMPORT TAB STATE
    // -------------------------------------------------------------
    const [importModule, setImportModule] = useState<'clientes' | 'maquinas' | 'lecturas'>('clientes');
    const [importPreview, setImportPreview] = useState<any[]>([]);
    const [importStats, setImportStats] = useState<any>(null);
    const [importErrors, setImportErrors] = useState<string[]>([]);
    const [importDuplicates, setImportDuplicates] = useState<any[]>([]);
    const [isImporting, setIsImporting] = useState(false);
    const importFileInputRef = useRef<HTMLInputElement>(null);

    // -------------------------------------------------------------
    // BACKUP & RESTORE STATE
    // -------------------------------------------------------------
    const [backupHistory, setBackupHistory] = useState<any[]>([]);
    const [isBackingUp, setIsBackingUp] = useState(false);
    const [isRestoring, setIsRestoring] = useState(false);
    const [restoreConfirmText, setRestoreConfirmText] = useState('');
    const restoreFileInputRef = useRef<HTMLInputElement>(null);

    // -------------------------------------------------------------
    // CLEANUP TAB STATE
    // -------------------------------------------------------------
    const [diagnosedIssues, setDiagnosedIssues] = useState<DiagnosedIssue[]>([]);
    const [selectedIssues, setSelectedIssues] = useState<string[]>([]);
    const [isDiagnosing, setIsDiagnosing] = useState(false);
    const [isCleaning, setIsCleaning] = useState(false);

    // -------------------------------------------------------------
    // AUDIT LOG STATE
    // -------------------------------------------------------------
    const [auditLogs, setAuditLogs] = useState<any[]>([]);
    const [auditSearchQuery, setAuditSearchQuery] = useState('');
    const [auditModuleFilter, setAuditModuleFilter] = useState('');
    const [auditActionFilter, setAuditActionFilter] = useState('');
    const [isLoadingAudit, setIsLoadingAudit] = useState(false);

    // Load Audit Logs and Backups history
    const loadAuditLogs = async () => {
        setIsLoadingAudit(true);
        const res = await getAuditLogsAction();
        if (res.success && res.logs) {
            setAuditLogs(res.logs);
            // Filter logs for backups
            const backups = res.logs.filter((l: any) => l.module === 'datos' && (l.action === 'backup' || l.action === 'restauracion'));
            setBackupHistory(backups);
        }
        setIsLoadingAudit(false);
    };

    useEffect(() => {
        loadAuditLogs();
    }, [currentSubTab]);

    // -------------------------------------------------------------
    // 1. EXPORTATION HANDLER
    // -------------------------------------------------------------
    const handleExport = async () => {
        setIsExporting(true);
        try {
            // Pick corresponding dataset from state
            let targetData: any[] = [];
            if (exportModule === 'clientes') {
                targetData = clients;
            } else if (exportModule === 'maquinas') {
                targetData = machines;
            } else if (exportModule === 'alquileres') {
                targetData = rentals;
            } else if (exportModule === 'abonos') {
                targetData = abonos;
            } else if (exportModule === 'lecturas') {
                targetData = readings;
            } else if (exportModule === 'tickets') {
                targetData = tickets;
            }

            // Apply filters if selected
            if (exportStatusFilter) {
                if (exportModule === 'clientes') {
                    const isActive = exportStatusFilter === 'activo';
                    targetData = targetData.filter(c => isActive ? c.active !== false : c.active === false);
                } else if (exportModule === 'maquinas') {
                    targetData = targetData.filter(m => m.status === exportStatusFilter);
                } else if (exportModule === 'alquileres') {
                    targetData = targetData.filter(r => r.status === exportStatusFilter);
                } else if (exportModule === 'lecturas') {
                    targetData = targetData.filter(rd => rd.status === exportStatusFilter);
                } else if (exportModule === 'tickets') {
                    targetData = targetData.filter(t => t.status === exportStatusFilter);
                }
            }

            const response = await fetch(`/api/export?user=${encodeURIComponent(currentUser?.fullname || 'Administrativo')}`, {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json'
                },
                body: JSON.stringify({
                    module: exportModule,
                    format: exportFormat,
                    data: targetData
                })
            });

            if (!response.ok) {
                throw new Error('La respuesta del servidor no fue satisfactoria.');
            }

            const blob = await response.blob();
            const downloadUrl = window.URL.createObjectURL(blob);
            const a = document.createElement('a');
            a.href = downloadUrl;
            a.download = `export_${exportModule}_${new Date().toISOString().split('T')[0]}.${exportFormat}`;
            document.body.appendChild(a);
            a.click();
            a.remove();
            window.URL.revokeObjectURL(downloadUrl);

            alert('┬íExportaci├│n descargada correctamente!');
        } catch (error: any) {
            console.error(error);
            alert('Error al intentar exportar los datos: ' + error.message);
        } finally {
            setIsExporting(false);
        }
    };

    // -------------------------------------------------------------
    // 2. CSV IMPORT HANDLERS
    // -------------------------------------------------------------
    const handleImportFileSelect = () => {
        importFileInputRef.current?.click();
    };

    const handleImportFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
        const file = e.target.files?.[0];
        if (!file) return;

        setIsImporting(true);
        const reader = new FileReader();
        reader.onload = async (event) => {
            try {
                const csvText = event.target?.result as string;

                const response = await fetch('/api/import', {
                    method: 'POST',
                    headers: {
                        'Content-Type': 'application/json'
                    },
                    body: JSON.stringify({
                        module: importModule,
                        csvText,
                        existingData: { clients, machines, readings }
                    })
                });

                const res = await response.json();
                if (!response.ok) {
                    throw new Error(res.error || 'Error al procesar el archivo CSV.');
                }

                setImportPreview(res.preview || []);
                setImportStats(res.stats || null);
                setImportErrors(res.errors || []);
                setImportDuplicates(res.duplicates || []);
            } catch (err: any) {
                console.error(err);
                alert(err.message || 'Error al validar el CSV.');
                setImportPreview([]);
                setImportStats(null);
                setImportErrors([]);
                setImportDuplicates([]);
            } finally {
                setIsImporting(false);
                if (importFileInputRef.current) importFileInputRef.current.value = '';
            }
        };
        reader.readAsText(file);
    };

    const confirmImport = async () => {
        if (!importPreview.length || isImporting) return;

        const validItems = importPreview.filter(item => item.isValid);
        if (validItems.length === 0) {
            alert('No hay registros v├ílidos para importar en el CSV.');
            return;
        }

        const confirmMsg = importDuplicates.length > 0 
            ? `Se importar├ín ${validItems.length} registros v├ílidos. Hay duplicados detectados. ┬┐Desea sobrescribir o ignorar duplicados? Presione Aceptar para unir los datos.`
            : `┬┐Confirmas la importaci├│n de ${validItems.length} registros v├ílidos en el sistema?`;

        if (confirm(confirmMsg)) {
            setIsImporting(true);
            try {
                if (importModule === 'clientes') {
                    setClients(prev => {
                        const filtered = prev.filter(c => !validItems.some(v => v.cuit === c.cuit));
                        const cleanedValids = validItems.map(({ isValid, errors, isDuplicate, ...rest }) => rest);
                        return [...filtered, ...cleanedValids];
                    });
                } else if (importModule === 'maquinas') {
                    setMachines(prev => {
                        const filtered = prev.filter(m => !validItems.some(v => v.serial === m.serial));
                        const cleanedValids = validItems.map(({ isValid, errors, isDuplicate, ...rest }) => rest);
                        return [...filtered, ...cleanedValids];
                    });
                } else if (importModule === 'lecturas') {
                    setReadings(prev => {
                        const filtered = prev.filter(r => !validItems.some(v => v.machineId === r.machineId && v.month === r.month));
                        const cleanedValids = validItems.map(({ isValid, errors, isDuplicate, ...rest }) => rest);
                        return [...filtered, ...cleanedValids];
                    });
                }

                // Log audit action
                await addAuditLogAction({
                    module: 'datos',
                    action: 'importar',
                    details: `Importaci├│n CSV para "${importModule.toUpperCase()}" ejecutada exitosamente. Total registros insertados: ${validItems.length}.`,
                    user: currentUser?.fullname || 'Administrativo'
                });

                alert('┬íDatos importados y sincronizados correctamente!');
                setImportPreview([]);
                setImportStats(null);
                setImportErrors([]);
                setImportDuplicates([]);
            } catch (err: any) {
                alert('Ocurri├│ un error al persistir los datos: ' + err.message);
            } finally {
                setIsImporting(false);
            }
        }
    };

    const cancelImportPreview = () => {
        setImportPreview([]);
        setImportStats(null);
        setImportErrors([]);
        setImportDuplicates([]);
    };

    // -------------------------------------------------------------
    // 3. TURSO DATABASE BACKUP & RESTORE
    // -------------------------------------------------------------
    const handleTursoBackup = async () => {
        setIsBackingUp(true);
        try {
            const userFullname = currentUser?.fullname || 'Administrativo';
            const response = await fetch(`/api/backup?user=${encodeURIComponent(userFullname)}`);
            if (!response.ok) {
                throw new Error('Error de comunicaci├│n con el Route Handler de backup.');
            }

            const blob = await response.blob();
            const downloadUrl = window.URL.createObjectURL(blob);
            const a = document.createElement('a');
            a.href = downloadUrl;
            a.download = `turso_backup_${new Date().toISOString().split('T')[0]}_${Date.now()}.json`;
            document.body.appendChild(a);
            a.click();
            a.remove();
            window.URL.revokeObjectURL(downloadUrl);

            await loadAuditLogs();
            alert('┬íSnapshot de base de datos Turso descargado exitosamente!');
        } catch (err: any) {
            console.error(err);
            alert('Ocurri├│ un error al generar el backup de Turso: ' + err.message);
        } finally {
            setIsBackingUp(false);
        }
    };

    const handleRestoreFileSelect = () => {
        restoreFileInputRef.current?.click();
    };

    const handleRestoreFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
        const file = e.target.files?.[0];
        if (!file) return;

        const reader = new FileReader();
        reader.onload = async (event) => {
            try {
                const parsed = JSON.parse(event.target?.result as string);

                // Confirm dialogs
                if (!parsed.clients || !parsed.machines || !parsed.plans || !parsed.users) {
                    alert('El archivo no parece ser un snapshot v├ílido de base de datos Turso (faltan tablas cr├¡ticas).');
                    return;
                }

                const warningConfirm = confirm(
                    'ÔÜá´©Å ┬íATENCI├ôN CR├ìTICA! Restaurar la base de datos reemplazar├í permanentemente TODOS los registros actuales (Clientes, M├íquinas, Alquileres, Abonos, Lecturas, Tickets y Configuraciones) en la nube de Turso y en tu almacenamiento local. ┬┐Est├ís absolutamente seguro de continuar?'
                );

                if (!warningConfirm) return;

                const codeWord = prompt('Para proceder, escribe la palabra "RESTAURAR" en may├║sculas:');
                if (codeWord !== 'RESTAURAR') {
                    alert('Operaci├│n cancelada. El c├│digo de confirmaci├│n no coincide.');
                    return;
                }

                setIsRestoring(true);
                const userFullname = currentUser?.fullname || 'Administrativo';
                const response = await fetch(`/api/backup?user=${encodeURIComponent(userFullname)}`, {
                    method: 'POST',
                    headers: {
                        'Content-Type': 'application/json'
                    },
                    body: JSON.stringify(parsed)
                });

                const res = await response.json();
                if (!response.ok) {
                    throw new Error(res.error || 'Error al restaurar la base de datos Turso.');
                }

                // Sincronizar estado local en React (que luego se autoguarda a localStorage)
                setClients(parsed.clients || []);
                setMachines(parsed.machines || []);
                setReadings(parsed.readings || []);
                setTickets(parsed.tickets || []);
                setAbonos(parsed.plans || parsed.abonos || []);
                setUsers(parsed.users || []);
                if (parsed.rentals) setRentals(parsed.rentals);

                await loadAuditLogs();
                alert('┬íFelicidades! La restauraci├│n transaccional de Turso y el estado local se complet├│ correctamente.');
            } catch (err: any) {
                console.error(err);
                alert('Error al restaurar la copia de seguridad: ' + err.message);
            } finally {
                setIsRestoring(false);
                if (restoreFileInputRef.current) restoreFileInputRef.current.value = '';
            }
        };
        reader.readAsText(file);
    };

