'use server';

import { db } from '@/infrastructure/db/client';
import { readings } from '@/infrastructure/db/schema/readings';
import { machines } from '@/infrastructure/db/schema/machines';
import { plans } from '@/infrastructure/db/schema/plans';
import { eq, and } from 'drizzle-orm';
import { auditReading } from '@/domain/reading/audit';
import { calculateBilling } from '@/domain/reading/billing';
import { revalidatePath } from 'next/cache';

export interface ReadingInput {
  id?: string;
  machineId: string;
  month: string;
  initial: number;
  final: number;
  readingStatus: string;
  billingStatus: string;
  collectionStatus: string;
  comments?: string;
  invoiceNumber?: string;
  invoiceDate?: string;
  creditNote: number;
  creditNoteReason?: string;
  debitNote: number;
  debitNoteReason?: string;
  invoiceFile?: string;
}

/**
 * Server Action para guardar (crear o editar) una Lectura mensual de un equipo.
 * Aplica auditor├¡a del dominio, calcula costos/excedentes/IVA e incrementa el contador de la m├íquina.
 */
export async function saveReadingAction(input: ReadingInput) {
  if (input.final < input.initial) {
    return { error: 'La lectura final no puede ser menor a la lectura inicial.' };
  }

  try {
    // 1. Obtener datos de la m├íquina y abono asociado
    const machineResults = await db.select().from(machines).where(eq(machines.id, input.machineId)).limit(1);
    const machine = machineResults[0];
    if (!machine) return { error: 'Equipo no encontrado.' };

    if (!machine.clientId) return { error: 'El equipo no est├í asignado a ning├║n cliente para facturaci├│n.' };
    if (!machine.abonoId) return { error: 'El equipo no tiene un plan/abono asignado.' };

    const planResults = await db.select().from(plans).where(eq(plans.id, machine.abonoId)).limit(1);
    const plan = planResults[0];
    if (!plan) return { error: 'Plan/abono no encontrado.' };

    // 2. Obtener historial para la auditor├¡a de consumos promedio
    const historyList = await db
      .select({ initial: readings.initial, final: readings.final })
      .from(readings)
      .where(and(eq(readings.machineId, input.machineId)));

    // 3. Ejecutar la auditor├¡a del dominio (validaci├│n de anomal├¡as y reglas de negocio)
    const isUnofficial = input.billingStatus === 'informal' || false;
    const auditAlerts = auditReading({
      initial: input.initial,
      final: input.final,
      limit: plan.limit,
      price: plan.price,
      excessPrice: plan.excessPrice,
      applyIva: machine.applyIva,
      ivaRate: plan.ivaRate,
      isUnofficial,
      creditNote: input.creditNote,
      debitNote: input.debitNote,
      billingStatus: input.billingStatus,
      invoiceNumber: input.invoiceNumber,
      invoiceDate: input.invoiceDate,
      historicalReadings: historyList,
    });

    // Si existen anomal├¡as de tipo "danger", se detiene la carga
    const hasDanger = auditAlerts.some(a => a.type === 'danger');
    if (hasDanger) {
      return { 
        error: 'No se pudo registrar la lectura debido a anomal├¡as cr├¡ticas de contadores.', 
        alerts: auditAlerts 
      };
    }

    // 4. Calcular el subtotal y total facturable
    const billing = calculateBilling({
      initial: input.initial,
      final: input.final,
      price: plan.price,
      limit: plan.limit,
      excessPrice: plan.excessPrice,
      applyIva: machine.applyIva,
      ivaRate: plan.ivaRate,
      isUnofficial,
      creditNote: input.creditNote,
      debitNote: input.debitNote,
    });

    // Calcular fecha de vencimiento (10 d├¡as despu├®s de emitir la factura)
    let dueDate: string | null = null;
    if (input.invoiceDate && (input.billingStatus === 'facturada' || input.billingStatus === 'enviada')) {
      const d = new Date(input.invoiceDate);
      d.setDate(d.getDate() + 10);
      dueDate = d.toISOString().split('T')[0];
    }

    // Bit├ícora de trazabilidad
    const timelineEntry = {
      timestamp: Date.now(),
      action: input.id ? 'Modificaci├│n' : 'Carga Lectura',
      description: `Lectura cargada: ${input.initial} inicial -> ${input.final} final. Neto: $${billing.netCost}, Total: $${billing.total}`,
      user: 'Administrativo',
    };

    let existingHistory: any[] = [];
    if (input.id) {
      const existingResults = await db.select({ history: readings.history }).from(readings).where(eq(readings.id, input.id)).limit(1);
      if (existingResults[0]) {
        existingHistory = existingResults[0].history as any[];
      }
    }
    const finalHistory = [...existingHistory, timelineEntry];

    const readingData = {
      machineId: input.machineId,
      clientId: machine.clientId,
      abonoId: machine.abonoId,
      month: input.month,
      initial: input.initial,
      final: input.final,
      readingStatus: input.readingStatus,
      billingStatus: input.billingStatus,
      collectionStatus: input.collectionStatus,
      comments: input.comments || null,
      invoiceNumber: input.invoiceNumber || null,
      invoiceDate: input.invoiceDate || null,
      dueDate,
      paymentAmount: input.collectionStatus === 'cobrado' ? billing.total : 0,
      paymentDate: input.collectionStatus === 'cobrado' ? new Date().toISOString().split('T')[0] : null,
      isUnofficial,
      creditNote: input.creditNote,
      creditNoteReason: input.creditNoteReason || null,
      debitNote: input.debitNote,
      debitNoteReason: input.debitNoteReason || null,
      invoiceFile: input.invoiceFile || null,
      history: finalHistory,
    };

    if (input.id) {
      await db.update(readings).set(readingData).where(eq(readings.id, input.id));
    } else {
      const newId = 'read-' + Date.now();
      await db.insert(readings).values({
        id: newId,
        ...readingData,
      });
    }

    // 5. Sincronizar el acumulador/contador de la m├íquina a la ├║ltima lectura final
    await db
      .update(machines)
      .set({ machineCounter: input.final, updatedAt: new Date() })
      .where(eq(machines.id, input.machineId));

    revalidatePath('/lecturas');
    return { success: true, alerts: auditAlerts };
  } catch (error: any) {
    console.error('Error al guardar la lectura mensual:', error);
    return { error: 'Error del servidor al registrar la lectura en la base de datos.' };
  }
}

import { NextResponse } from 'next/server';
import { db } from '@/infrastructure/db/client';
import { users } from '@/infrastructure/db/schema/users';
import { eq } from 'drizzle-orm';
import { hashPassword, verifyPassword, validatePasswordStrength } from '@/lib/auth/passwordService';
import { verifyAuth } from '@/lib/auth/authService';
import { createSession, revokeAllSessionsForUser } from '@/infrastructure/auth/session';
import { logSecurityEvent } from '@/lib/security/audit';

export async function POST(request: Request) {
  const ip = request.headers.get('x-forwarded-for') || '127.0.0.1';
  const userAgent = request.headers.get('user-agent') || 'Unknown';

  try {
    // 1. Validar autenticaci├│n
    let session;
    try {
      session = await verifyAuth();
    } catch (e: any) {
      return NextResponse.json({
        ok: false,
        error: { code: 'UNAUTHORIZED', message: 'Sesi├│n no v├ílida.' }
      }, { status: 401 });
    }

    const { currentPassword, newPassword } = await request.json();

    if (!currentPassword || !newPassword) {
      return NextResponse.json({
        ok: false,
        error: { code: 'BAD_REQUEST', message: 'Contrase├▒a actual y nueva son requeridas.' }
      }, { status: 400 });
    }

    // 2. Validar complejidad de contrase├▒a nueva
    const strength = validatePasswordStrength(newPassword);
    if (!strength.isValid) {
      return NextResponse.json({
        ok: false,
        error: { code: 'BAD_REQUEST', message: strength.error }
      }, { status: 400 });
    }

    // 3. Buscar usuario en base de datos
    const results = await db.select().from(users).where(eq(users.id, session.userId)).limit(1);
    const user = results[0];

    if (!user) {
      return NextResponse.json({
        ok: false,
        error: { code: 'NOT_FOUND', message: 'Usuario no encontrado.' }
      }, { status: 404 });
    }

    // 4. Verificar contrase├▒a actual
    const passwordMatch = await verifyPassword(currentPassword, user.passwordHash);
    if (!passwordMatch) {
      return NextResponse.json({
        ok: false,
        error: { code: 'UNAUTHORIZED', message: 'La contrase├▒a actual ingresada es incorrecta.' }
      }, { status: 401 });
    }

    // 5. Hashear nueva contrase├▒a e insertarla
    const newPasswordHash = await hashPassword(newPassword);

    await db
      .update(users)
      .set({
        passwordHash: newPasswordHash,
      })
      .where(eq(users.id, user.id));

    // 6. Invalidar todas las sesiones previas
    await revokeAllSessionsForUser(user.id);

    // 7. Re-crear sesi├│n activa para el dispositivo actual
    await createSession(
      {
        id: user.id,
        username: user.username,
        fullname: user.fullname,
        role: user.role,
        isMaster: user.isMaster === 1,
      },
      ip,
      userAgent
    );

    // Loguear auditor├¡a
    await logSecurityEvent('password_change_success', user.username, `Contrase├▒a cambiada por el usuario (${user.isMaster === 1 ? 'master' : 'usuario'}). IP: ${ip}`);

    return NextResponse.json({
      ok: true,
      message: 'Su contrase├▒a ha sido cambiada correctamente.'
    });
  } catch (error: any) {
    console.error('Error en API change-password:', error);
    return NextResponse.json({
      ok: false,
      error: { code: 'INTERNAL_ERROR', message: 'Ocurri├│ un error interno.' }
    }, { status: 500 });
  }
}

import { NextResponse } from 'next/server';
import { db } from '@/infrastructure/db/client';
import { users } from '@/infrastructure/db/schema/users';
import { passwordResetTokens } from '@/infrastructure/db/schema/passwordResetTokens';
import { eq, or, and, gt } from 'drizzle-orm';
import { webcrypto } from 'crypto';
import nodemailer from 'nodemailer';
import { logSecurityEvent } from '@/lib/security/audit';

async function hashToken(token: string): Promise<string> {
  const msgBuffer = new TextEncoder().encode(token);
  const hashBuffer = await webcrypto.subtle.digest('SHA-256', msgBuffer);
  const hashArray = Array.from(new Uint8Array(hashBuffer));
  return hashArray.map(b => b.toString(16).padStart(2, '0')).join('');
}

function generateResetToken(): string {
  const bytes = crypto.getRandomValues(new Uint8Array(32));
  return Array.from(bytes).map(b => b.toString(16).padStart(2, '0')).join('');
}

export async function POST(request: Request) {
  try {
    const { identity } = await request.json(); // Puede ser username o email

    if (!identity) {
      return NextResponse.json({ error: 'Usuario o correo electr├│nico requerido.' }, { status: 400 });
    }

    const ip = request.headers.get('x-forwarded-for') || '127.0.0.1';
    const userAgent = request.headers.get('user-agent') || 'Unknown';
    const fifteenMinutesAgo = new Date(Date.now() - 15 * 60 * 1000);

    // 1. IP Rate Limiting Check
    const recentIpTokens = await db
      .select()
      .from(passwordResetTokens)
      .where(
        and(
          eq(passwordResetTokens.requestedIp, ip),
          gt(passwordResetTokens.createdAt, fifteenMinutesAgo)
        )
      );

    if (recentIpTokens.length >= 5) {
      await logSecurityEvent(
        'forbidden_access',
        identity,
        `Solicitud bloqueada por l├¡mite de tasa de IP (Rate Limit). IP: ${ip}`
      );
      return NextResponse.json({
        error: 'Demasiadas solicitudes de recuperaci├│n desde esta direcci├│n IP. Por favor, espere 15 minutos.'
      }, { status: 429 });
    }

    // 2. Buscar usuario
    const results = await db
      .select()
      .from(users)
      .where(or(eq(users.username, identity), eq(users.email, identity)))
      .limit(1);

    const user = results[0];

    // Siempre retornar mensaje gen├®rico de ├®xito para evitar enumeraci├│n
    const genericResponse = {
      success: true,
      message: 'Si la cuenta existe, se ha enviado un correo electr├│nico con instrucciones para restablecer su contrase├▒a.',
    };

    if (!user) {
      await logSecurityEvent(
        'forgot_password_requested',
        identity,
        `Solicitud de recuperaci├│n para usuario inexistente. IP: ${ip}`
      );
      return NextResponse.json(genericResponse);
    }

    // 3. User Rate Limiting Check
    const recentTokens = await db
      .select()
      .from(passwordResetTokens)
      .where(
        and(
          eq(passwordResetTokens.userId, user.id),
          gt(passwordResetTokens.createdAt, fifteenMinutesAgo)
        )
      );

    if (recentTokens.length >= 3) {
      await logSecurityEvent(
        'forbidden_access',
        user.username,
        `Solicitud bloqueada por l├¡mite de tasa (Rate Limit). IP: ${ip}`
      );
      return NextResponse.json({
        error: 'Demasiadas solicitudes de recuperaci├│n de contrase├▒a. Por favor, espere 15 minutos.'
      }, { status: 429 });
    }

    // 2. Generar token de recuperaci├│n seguro
    const rawToken = generateResetToken();
    const tokenHash = await hashToken(rawToken);
    const expiresAt = new Date(Date.now() + 15 * 60 * 1000); // 15 minutos de expiraci├│n

    const tokenId = 'tok-' + Date.now() + '-' + Math.random().toString(36).substring(2, 6);

    // 3. Registrar el token en base de datos
    await db.insert(passwordResetTokens).values({
      id: tokenId,
      userId: user.id,
      tokenHash,
      expiresAt,
      requestedIp: ip,
      requestedUserAgent: userAgent,
    });

    await logSecurityEvent(
      'forgot_password_requested',
      user.username,
      `Solicitud de recuperaci├│n de contrase├▒a iniciada. IP: ${ip}`
    );

    // 4. Enviar correo usando Nodemailer con Yahoo SMTP
    const yahooEmail = process.env.YAHOO_EMAIL;
    const yahooPassword = process.env.YAHOO_APP_PASSWORD;

    if (!yahooEmail || !yahooPassword) {
      console.warn('Credenciales SMTP de Yahoo ausentes. Impresi├│n del token en logs locales para desarrollo.');
      console.log(`[DESARROLLO] Token de reset para ${user.username}: ${rawToken}`);
      return NextResponse.json(genericResponse);
    }

    const transporter = nodemailer.createTransport({
      service: 'yahoo',
      auth: {
        user: yahooEmail,
        pass: yahooPassword,
      },
    });

    const appUrl = process.env.NEXT_PUBLIC_APP_URL || 'http://localhost:3000';
    const resetLink = `${appUrl}/reset-password?token=${rawToken}`;

    const mailOptions = {
      from: `"M&S Soporte" <${yahooEmail}>`,
      to: user.email,
      subject: 'Restablecimiento de Contrase├▒a - M&S Tecnolog├¡a Digital',
      html: `
        <div style="font-family: sans-serif; max-width: 600px; margin: 0 auto; padding: 20px; border: 1px solid #e2e8f0; rounded: 12px;">
          <h2 style="color: #0f172a;">M&S Tecnolog├¡a Digital</h2>
          <p>Hola, <strong>${user.fullname}</strong>,</p>
          <p>Hemos recibido una solicitud para restablecer la contrase├▒a de tu cuenta administrativa.</p>
          <p>Para continuar, haz clic en el siguiente bot├│n (este enlace expira en 15 minutos):</p>
          <div style="margin: 30px 0; text-align: center;">
            <a href="${resetLink}" style="background-color: #3b82f6; color: white; padding: 12px 24px; text-decoration: none; border-radius: 8px; font-weight: bold; display: inline-block;">
              Restablecer Contrase├▒a
            </a>
          </div>
          <p style="color: #64748b; font-size: 12px;">
            Si el bot├│n no funciona, copia y pega esta direcci├│n en tu navegador:<br>
            <a href="${resetLink}" style="color: #3b82f6;">${resetLink}</a>
