export async function PATCH(request: Request) {
  const ip = request.headers.get('x-forwarded-for') || '127.0.0.1';
  const userAgent = request.headers.get('user-agent') || 'Unknown';

  try {
    const session = await getSession(request);
    if (!session) {
      return NextResponse.json({
        ok: false,
        error: { code: 'UNAUTHORIZED', message: 'Sesi├│n no v├ílida.' }
      }, { status: 401 });
    }

    const body = await request.json();
    const { fullname, email, username, phone, whatsapp } = body;

    const results = await db.select().from(users).where(eq(users.id, session.userId)).limit(1);
    const user = results[0];

    if (!user) {
      return NextResponse.json({
        ok: false,
        error: { code: 'NOT_FOUND', message: 'Usuario no encontrado.' }
      }, { status: 404 });
    }

    const isMaster = user.isMaster === 1 || user.id === 'user-admin';

    // 1. Validaciones de Duplicados
    if (email && email.trim().toLowerCase() !== user.email) {
      const emailDup = await db
        .select()
        .from(users)
        .where(and(eq(users.email, email.trim().toLowerCase()), ne(users.id, user.id)))
        .limit(1);

      if (emailDup.length > 0) {
        return NextResponse.json({
          ok: false,
          error: { code: 'CONFLICT', message: 'El correo electr├│nico ya se encuentra registrado por otro usuario.' }
        }, { status: 409 });
      }
    }

    if (username && username.trim().toLowerCase() !== user.username) {
      const usernameDup = await db
        .select()
        .from(users)
        .where(and(eq(users.username, username.trim().toLowerCase()), ne(users.id, user.id)))
        .limit(1);

      if (usernameDup.length > 0) {
        return NextResponse.json({
          ok: false,
          error: { code: 'CONFLICT', message: 'El nombre de usuario ya se encuentra registrado.' }
        }, { status: 409 });
      }
    }

    // 2. Preparar valores de actualizaci├│n
    const updateValues: any = {
      updatedAt: new Date(),
    };

    if (fullname) updateValues.fullname = fullname.trim();
    if (email) updateValues.email = email.trim().toLowerCase();
    if (username) updateValues.username = username.trim().toLowerCase();
    if (phone !== undefined) updateValues.phone = phone || null;
    if (whatsapp !== undefined) updateValues.whatsapp = whatsapp || null;

    // Actualizar en base de datos
    await db.update(users).set(updateValues).where(eq(users.id, user.id));

    // Loguear auditor├¡a
    await logSecurityEvent('user_updated', user.username, `Perfil del usuario (${isMaster ? 'master' : 'usuario'}) actualizado por s├¡ mismo. IP: ${ip}`);

    // Obtener los datos actualizados
    const updatedUserResults = await db.select().from(users).where(eq(users.id, user.id)).limit(1);
    const updatedUser = updatedUserResults[0];

    // 3. Regenerar cookie de sesi├│n
    await createSession(
      {
        id: updatedUser.id,
        username: updatedUser.username,
        fullname: updatedUser.fullname,
        role: updatedUser.role,
        isMaster: updatedUser.isMaster === 1,
      },
      ip,
      userAgent
    );

    const { passwordHash: _, ...safeUser } = updatedUser;

    return NextResponse.json({
      ok: true,
      data: {
        user: safeUser,
      }
    });
  } catch (error: any) {
    console.error('Error en PATCH /api/auth/me:', error);
    return NextResponse.json({
      ok: false,
      error: { code: 'INTERNAL_ERROR', message: 'Ocurri├│ un error interno.' }
    }, { status: 500 });
  }
}

import { NextResponse } from 'next/server';
import { db } from '@/infrastructure/db/client';
import { users } from '@/infrastructure/db/schema/users';
import { passwordResetTokens } from '@/infrastructure/db/schema/passwordResetTokens';
import { eq, and, isNull } from 'drizzle-orm';
import { webcrypto } from 'crypto';
import { hashPassword, validatePasswordStrength } from '@/lib/auth/passwordService';
import { revokeAllSessionsForUser } from '@/infrastructure/auth/session';
import { logSecurityEvent } from '@/lib/security/audit';

async function hashToken(token: string): Promise<string> {
  const msgBuffer = new TextEncoder().encode(token);
  const hashBuffer = await webcrypto.subtle.digest('SHA-256', msgBuffer);
  const hashArray = Array.from(new Uint8Array(hashBuffer));
  return hashArray.map(b => b.toString(16).padStart(2, '0')).join('');
}

export async function POST(request: Request) {
  try {
    const { token, password } = await request.json();

    if (!token || !password) {
      return NextResponse.json({ error: 'Token y nueva contrase├▒a son requeridos.' }, { status: 400 });
    }

    const ip = request.headers.get('x-forwarded-for') || '127.0.0.1';

    // 1. Validar complejidad de contrase├▒a
    const strength = validatePasswordStrength(password);
    if (!strength.isValid) {
      return NextResponse.json({ error: strength.error }, { status: 400 });
    }

    // 2. Buscar token hasheado
    const tokenHash = await hashToken(token);

    const tokenResults = await db
      .select()
      .from(passwordResetTokens)
      .where(and(eq(passwordResetTokens.tokenHash, tokenHash), isNull(passwordResetTokens.usedAt)))
      .limit(1);

    const resetToken = tokenResults[0];

    if (!resetToken) {
      return NextResponse.json({
        error: 'El token de restablecimiento es inv├ílido, ya ha sido utilizado o ha expirado.',
      }, { status: 400 });
    }

    // 3. Validar expiraci├│n del token
    if (new Date() > resetToken.expiresAt) {
      return NextResponse.json({
        error: 'El token ha expirado. Por favor, solicite una nueva recuperaci├│n.',
      }, { status: 400 });
    }

    // 4. Buscar usuario para loguear auditor├¡a y actualizar contrase├▒a
    const userResults = await db.select().from(users).where(eq(users.id, resetToken.userId)).limit(1);
    const user = userResults[0];

    if (!user) {
      return NextResponse.json({ error: 'El usuario asociado a este token no existe.' }, { status: 400 });
    }

    // 5. Hashear nueva contrase├▒a y persistirla
    const newPasswordHash = await hashPassword(password);

    await db
      .update(users)
      .set({
        passwordHash: newPasswordHash,
        failedLoginAttempts: 0,
        lockedUntil: null,
      })
      .where(eq(users.id, user.id));

    // 6. Marcar token como utilizado
    await db
      .update(passwordResetTokens)
      .set({ usedAt: new Date() })
      .where(eq(passwordResetTokens.id, resetToken.id));

    // 7. Invalidar todas las sesiones activas del usuario (Seguridad proactiva)
    await revokeAllSessionsForUser(user.id);

    await logSecurityEvent(
      'password_reset_success',
      user.username,
      `Contrase├▒a restablecida con ├®xito mediante token de recuperaci├│n. IP: ${ip}`
    );

    return NextResponse.json({ success: true, message: 'Contrase├▒a cambiada con ├®xito.' });
  } catch (error: any) {
    console.error('Error en API reset-password:', error);
    return NextResponse.json({ error: 'Error del servidor al procesar la solicitud.' }, { status: 500 });
  }
}

