import { NextResponse } from 'next/server';
import { addAuditLogAction } from '@/app/actions/audit';

function escapeCSVCell(val: any): string {
  if (val === null || val === undefined) return '';
  let str = String(val);
  // Replace double quotes with escaped double quotes
  str = str.replace(/"/g, '""');
  // Wrap in quotes if it contains commas, newlines, or quotes
  if (str.includes(',') || str.includes('\n') || str.includes('\r') || str.includes('"')) {
    return `"${str}"`;
  }
  return str;
}

/**
 * POST: Genera y descarga un archivo exportado en CSV o JSON.
 */
export async function POST(request: Request) {
  try {
    const { searchParams } = new URL(request.url);
    const user = searchParams.get('user') || 'dmoyano';

    const payload = await request.json();
    const { module, format, data } = payload;

    if (!module || !format || !Array.isArray(data)) {
      return NextResponse.json({ error: 'Par├ímetros de exportaci├│n inv├ílidos.' }, { status: 400 });
    }

    let fileContent = '';
    let contentType = 'text/plain';
    let fileExtension = 'txt';

    if (format === 'json') {
      fileContent = JSON.stringify(data, null, 2);
      contentType = 'application/json';
      fileExtension = 'json';
    } else if (format === 'csv') {
      contentType = 'text/csv;charset=utf-8';
      fileExtension = 'csv';

      if (data.length === 0) {
        fileContent = 'No hay datos para exportar';
      } else {
        // Extract headers from keys of first object
        const sample = data[0];
        const headers = Object.keys(sample);
        const headerRow = headers.map(escapeCSVCell).join(',');

        const rows = data.map(item => {
          return headers.map(h => escapeCSVCell(item[h])).join(',');
        });

        // Add BOM (Byte Order Mark) for Excel UTF-8 compatibility
        fileContent = '\uFEFF' + [headerRow, ...rows].join('\n');
      }
    }

    // Log this export audit log entry
    await addAuditLogAction({
      module: 'datos',
      action: 'exportar',
      details: `Exportaci├│n del m├│dulo "${module.toUpperCase()}" generada con ├®xito en formato ${format.toUpperCase()}. Total registros: ${data.length}.`,
      user
    });

    return new Response(fileContent, {
      status: 200,
      headers: {
        'Content-Type': contentType,
        'Content-Disposition': `attachment; filename="export_${module}_${new Date().toISOString().split('T')[0]}.${fileExtension}"`,
      },
    });
  } catch (error: any) {
    console.error('Error al exportar datos:', error);
    return NextResponse.json({ error: 'Error del servidor al exportar datos: ' + error.message }, { status: 500 });
  }
}

import { NextResponse } from 'next/server';

function parseCSV(text: string): string[][] {
  const lines: string[][] = [];
  let row: string[] = [];
  let inQuotes = false;
  let currentCell = '';

  for (let i = 0; i < text.length; i++) {
    const char = text[i];
    const nextChar = text[i + 1];

    if (char === '"') {
      if (inQuotes && nextChar === '"') {
        currentCell += '"';
        i++; // skip
      } else {
        inQuotes = !inQuotes;
      }
    } else if (char === ',' && !inQuotes) {
      row.push(currentCell.trim());
      currentCell = '';
    } else if ((char === '\r' || char === '\n') && !inQuotes) {
      if (char === '\r' && nextChar === '\n') {
        i++;
      }
      row.push(currentCell.trim());
      if (row.some(c => c !== '')) {
        lines.push(row);
      }
      row = [];
      currentCell = '';
    } else {
      currentCell += char;
    }
  }
  if (currentCell || row.length > 0) {
    row.push(currentCell.trim());
    if (row.some(c => c !== '')) {
      lines.push(row);
    }
  }
  return lines;
}

/**
 * POST: Procesa un archivo CSV y devuelve la previsualizaci├│n y validaci├│n.
 */
export async function POST(request: Request) {
  try {
    const payload = await request.json();
    const { module, csvText, existingData } = payload;

    if (!module || !csvText) {
      return NextResponse.json({ error: 'Par├ímetros de importaci├│n incompletos.' }, { status: 400 });
    }

    const lines = parseCSV(csvText);
    if (lines.length < 2) {
      return NextResponse.json({ error: 'El archivo CSV debe contener una fila de encabezados y al menos una fila de datos.' }, { status: 400 });
    }

    const headers = lines[0].map(h => h.toLowerCase().trim());
    const dataRows = lines.slice(1);

    const preview: any[] = [];
    const errors: string[] = [];
    const duplicates: any[] = [];

    // Helper functions for duplicate check in existing data arrays sent by the client
    const existingClients = existingData?.clients || [];
    const existingMachines = existingData?.machines || [];
    const existingReadings = existingData?.readings || [];

    if (module === 'clientes') {
      // Expected headers mapping
      const nameIdx = headers.findIndex(h => h === 'nombre' || h === 'name');
      const cuitIdx = headers.findIndex(h => h === 'cuit');
      const taxIdx = headers.findIndex(h => h === 'categoria_iva' || h === 'taxcategory');
      const addressIdx = headers.findIndex(h => h === 'direccion' || h === 'address');
      const phoneIdx = headers.findIndex(h => h === 'telefono' || h === 'phone');
      const emailIdx = headers.findIndex(h => h === 'email');
      const notesIdx = headers.findIndex(h => h === 'notas' || h === 'notes');

      if (nameIdx === -1 || cuitIdx === -1) {
        return NextResponse.json({ error: 'El CSV de clientes debe incluir obligatoriamente las columnas "Nombre" y "CUIT".' }, { status: 400 });
      }

      dataRows.forEach((row, index) => {
        const lineNum = index + 2;
        const name = row[nameIdx]?.trim() || '';
        const cuit = row[cuitIdx]?.trim() || '';
        const taxCategory = row[taxIdx]?.trim() || 'Responsable Inscripto';
        const address = row[addressIdx]?.trim() || '';
        const phone = row[phoneIdx]?.trim() || '';
        const email = row[emailIdx]?.trim() || '';
        const notes = row[notesIdx]?.trim() || '';

        const rowErrors: string[] = [];

        if (!name) {
          rowErrors.push(`L├¡nea ${lineNum}: El nombre es obligatorio.`);
        }
        if (!cuit) {
          rowErrors.push(`L├¡nea ${lineNum}: El CUIT es obligatorio.`);
        } else {
          // Normalize cuit for validation (removing spaces and hyphens)
          const cleanCuit = cuit.replace(/[^0-9]/g, '');
          if (cleanCuit.length !== 11) {
            rowErrors.push(`L├¡nea ${lineNum}: CUIT inv├ílido "${cuit}". Debe tener 11 d├¡gitos.`);
          }
        }

        const isDuplicate = existingClients.some((c: any) => c.cuit === cuit);

        const mappedItem = {
          id: 'client-import-' + Date.now() + '-' + index,
          name,
          cuit,
          taxCategory: ['Responsable Inscripto', 'Monotributista', 'Exento'].includes(taxCategory) ? taxCategory : 'Responsable Inscripto',
          address,
          phone,
          email,
          notes,
          debt: 0,
          active: true,
          isValid: rowErrors.length === 0,
          errors: rowErrors,
          isDuplicate
        };

        preview.push(mappedItem);
        if (rowErrors.length > 0) {
          errors.push(...rowErrors);
        }
        if (isDuplicate) {
          duplicates.push({ line: lineNum, label: `${name} (CUIT: ${cuit})` });
        }
      });

    } else if (module === 'maquinas') {
      const brandIdx = headers.findIndex(h => h === 'marca' || h === 'brand');
      const modelIdx = headers.findIndex(h => h === 'modelo' || h === 'model');
      const serialIdx = headers.findIndex(h => h === 'serie' || h === 'serial');
      const typeIdx = headers.findIndex(h => h === 'tipo' || h === 'type');
      const statusIdx = headers.findIndex(h => h === 'estado' || h === 'status');
      const counterIdx = headers.findIndex(h => h === 'contador' || h === 'currentcounter');
      const intervalIdx = headers.findIndex(h => h === 'intervalo_preventivo' || h === 'preventiveinterval');
      const applyIvaIdx = headers.findIndex(h => h === 'aplica_iva' || h === 'applyiva');

      if (brandIdx === -1 || modelIdx === -1 || serialIdx === -1) {
        return NextResponse.json({ error: 'El CSV de m├íquinas debe incluir obligatoriamente las columnas "Marca", "Modelo" y "Serie".' }, { status: 400 });
      }

      dataRows.forEach((row, index) => {
        const lineNum = index + 2;
        const brand = row[brandIdx]?.trim() || '';
        const model = row[modelIdx]?.trim() || '';
        const serial = row[serialIdx]?.trim() || '';
        const type = row[typeIdx]?.trim() || 'B&N';
        const status = row[statusIdx]?.trim() || 'Disponible';
        const currentCounter = parseInt(row[counterIdx]?.trim() || '0', 10);
        const preventiveInterval = parseInt(row[intervalIdx]?.trim() || '15000', 10);
        const applyIva = row[applyIvaIdx]?.trim().toLowerCase() === 'si' || row[applyIvaIdx]?.trim().toLowerCase() === 'true';

        const rowErrors: string[] = [];

        if (!brand) rowErrors.push(`L├¡nea ${lineNum}: La marca es obligatoria.`);
        if (!model) rowErrors.push(`L├¡nea ${lineNum}: El modelo es obligatorio.`);
        if (!serial) rowErrors.push(`L├¡nea ${lineNum}: El n├║mero de serie es obligatorio.`);
        if (isNaN(currentCounter) || currentCounter < 0) {
          rowErrors.push(`L├¡nea ${lineNum}: El contador de copias debe ser un n├║mero entero v├ílido.`);
        }

        const isDuplicate = existingMachines.some((m: any) => m.serial === serial);

        const mappedItem = {
          id: 'machine-import-' + Date.now() + '-' + index,
          clientId: null,
          abonoId: null,
          brand,
          model,
          serial,
          type: type === 'Color' ? 'Color' : 'B&N',
          currentCounter: isNaN(currentCounter) ? 0 : currentCounter,
          lastServiceCounter: isNaN(currentCounter) ? 0 : currentCounter,
          preventiveInterval: isNaN(preventiveInterval) ? 15000 : preventiveInterval,
          status: ['Disponible', 'Alquilada', 'En Taller', 'Alerta T├®cnica'].includes(status) ? status : 'Disponible',
          applyIva,
          isValid: rowErrors.length === 0,
          errors: rowErrors,
          isDuplicate
        };

        preview.push(mappedItem);
        if (rowErrors.length > 0) {
          errors.push(...rowErrors);
        }
        if (isDuplicate) {
          duplicates.push({ line: lineNum, label: `${brand} ${model} (S/N: ${serial})` });
        }
      });

    } else if (module === 'lecturas') {
      const serialIdx = headers.findIndex(h => h === 'serie_copiadora' || h === 'machineserial' || h === 'serial');
      const monthIdx = headers.findIndex(h => h === 'mes' || h === 'month');
      const initialIdx = headers.findIndex(h => h === 'inicial' || h === 'initial');
      const finalIdx = headers.findIndex(h => h === 'final' || h === 'final');
      const commentIdx = headers.findIndex(h => h === 'comentario' || h === 'readingcomment' || h === 'comment');

      if (serialIdx === -1 || monthIdx === -1 || initialIdx === -1 || finalIdx === -1) {
        return NextResponse.json({ error: 'El CSV de lecturas debe incluir las columnas "Serie_Copiadora", "Mes" (AAAA-MM), "Inicial" y "Final".' }, { status: 400 });
      }

      dataRows.forEach((row, index) => {
        const lineNum = index + 2;
        const serial = row[serialIdx]?.trim() || '';
        const month = row[monthIdx]?.trim() || '';
        const initial = parseInt(row[initialIdx]?.trim() || '0', 10);
        const final = parseInt(row[finalIdx]?.trim() || '0', 10);
        const readingComment = row[commentIdx]?.trim() || '';

        const rowErrors: string[] = [];

        if (!serial) rowErrors.push(`L├¡nea ${lineNum}: El n├║mero de serie de copiadora es obligatorio.`);

        const monthRegex = /^\d{4}-\d{2}$/;
        if (!month || !monthRegex.test(month)) {
          rowErrors.push(`L├¡nea ${lineNum}: El mes debe tener formato AAAA-MM (ej. 2026-07).`);
        }

        if (isNaN(initial) || initial < 0) {
          rowErrors.push(`L├¡nea ${lineNum}: El contador inicial debe ser un n├║mero entero v├ílido.`);
        }
        if (isNaN(final) || final < 0) {
          rowErrors.push(`L├¡nea ${lineNum}: El contador final debe ser un n├║mero entero v├ílido.`);
        }
        if (!isNaN(initial) && !isNaN(final) && final < initial) {
          rowErrors.push(`L├¡nea ${lineNum}: El contador final no puede ser menor al inicial.`);
        }

        // Find associated machine in state to link properly
        const machine = existingMachines.find((m: any) => m.serial === serial);
        if (!machine && serial) {
          rowErrors.push(`L├¡nea ${lineNum}: No se encontr├│ ninguna copiadora en inventario con S/N "${serial}".`);
        }

        const isDuplicate = machine && existingReadings.some((r: any) => r.machineId === machine.id && r.month === month);

        const mappedItem = {
          id: 'reading-import-' + Date.now() + '-' + index,
          machineId: machine ? machine.id : 'unknown',
          machineSerial: serial,
          month,
          initial: isNaN(initial) ? 0 : initial,
          final: isNaN(final) ? 0 : final,
          excessCount: 0,
          excessPrice: 0,
          netAmount: 0,
          ivaAmount: 0,
          totalAmount: 0,
          status: 'pending',
          readingStatus: 'cargada',
          readingComment: readingComment || undefined,
          isValid: rowErrors.length === 0,
          errors: rowErrors,
          isDuplicate
        };

        preview.push(mappedItem);
        if (rowErrors.length > 0) {
          errors.push(...rowErrors);
        }
        if (isDuplicate) {
          duplicates.push({ line: lineNum, label: `Lectura S/N: ${serial} - Mes: ${month}` });
        }
      });
    }

    const stats = {
      total: preview.length,
      ready: preview.filter(item => item.isValid).length,
      errors: preview.filter(item => !item.isValid).length,
      duplicates: duplicates.length
    };

    return NextResponse.json({
      success: true,
      preview,
      stats,
      errors,
      duplicates
    });

  } catch (error: any) {
    console.error('Error al procesar CSV para importaci├│n:', error);
    return NextResponse.json({ error: 'Error del servidor al procesar archivo: ' + error.message }, { status: 500 });
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { db } from '@/infrastructure/db/client';
import { sharedPdfs } from '@/infrastructure/db/schema/sharedPdfs';
import { eq } from 'drizzle-orm';

export async function GET(
  req: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    const { id } = await params;

    if (!id) {
      return new NextResponse('ID de PDF inv├ílido', { status: 400 });
    }

    // Consultar la base de datos Turso
    const records = await db
      .select()
      .from(sharedPdfs)
      .where(eq(sharedPdfs.id, id))
      .limit(1);

    if (records.length === 0) {
      return new NextResponse('Archivo PDF no encontrado.', { status: 404 });
    }

    const record = records[0];

    // Check expiration (30 days limit)
    const createdAt = new Date(record.createdAt);
    const thirtyDaysAgo = new Date();
    thirtyDaysAgo.setDate(thirtyDaysAgo.getDate() - 30);

    if (createdAt < thirtyDaysAgo) {
      return new NextResponse('El archivo PDF ha expirado.', { status: 404 });
    }

    const pdfBuffer = Buffer.from(record.pdfBase64, 'base64');

    // Devolver el archivo PDF con las cabeceras HTTP correctas
    return new NextResponse(pdfBuffer, {
      headers: {
        'Content-Type': 'application/pdf',
        'Content-Disposition': `inline; filename="${record.filename}"`,
        'Cache-Control': 'public, max-age=31536000, immutable',
      },
    });
  } catch (error: any) {
    console.error('Error al servir PDF:', error);
    return new NextResponse('Error del servidor al cargar el PDF.', { status: 500 });
  }
}

