import { NextResponse } from 'next/server';
import { db } from '@/infrastructure/db/client';
import { getSession } from '@/infrastructure/auth/session';
import { eq, sql } from 'drizzle-orm';
import {
  clients,
  machines,
  readings,
  tickets,
  plans,
  users,
  rentals,
  budgets,
} from '@/infrastructure/db/schema';
import {
  clientSyncSchema,
  machineSyncSchema,
  readingSyncSchema,
  ticketSyncSchema,
  planSyncSchema,
  userSyncSchema,
  rentalSyncSchema,
  budgetSyncSchema,
} from '@/lib/validation/syncSchemas';

export async function POST(request: Request) {
  try {
    const session = await getSession(request);
    if (!session) {
      return NextResponse.json({
        error: 'Sesi├│n no v├ílida.',
        code: 'UNAUTHORIZED'
      }, { status: 401 });
    }

    const body = await request.json();
    const { items } = body;

    if (!Array.isArray(items)) {
      return NextResponse.json({
        error: 'La carga ├║til debe contener un arreglo de cambios "items".',
        code: 'BAD_REQUEST'
      }, { status: 400 });
    }

    // Sort items by dependency order
    const ENTITY_TYPE_ORDER: Record<string, number> = {
      'users': 0,
      'clients': 1,
      'plans': 2,
      'abonos': 2,
      'machines': 3,
      'readings': 4,
      'rentals': 5,
      'tickets': 6,
      'budgets': 7
    };

    const getOrder = (item: any) => {
      const baseOrder = ENTITY_TYPE_ORDER[item.entityType] ?? 99;
      if (item.operation === 'delete') {
        return 100 - baseOrder;
      }
      return baseOrder;
    };

    const sortedItems = [...items].sort((a: any, b: any) => {
      if (a.entityType === b.entityType && a.entityId === b.entityId) {
        return items.indexOf(a) - items.indexOf(b);
      }
      const orderA = getOrder(a);
      const orderB = getOrder(b);
      if (orderA !== orderB) {
        return orderA - orderB;
      }
      return items.indexOf(a) - items.indexOf(b);
    });

    const results: any[] = [];

    await db.transaction(async (tx) => {
      for (const item of sortedItems) {
        const { id, entityId, entityType, operation, payload, updatedAt } = item;

        if (!id || !entityId || !entityType || !operation || !payload || !updatedAt) {
          results.push({
            id: id || 'unknown',
            status: 'failed',
            reason: 'missing_fields',
            message: 'Faltan campos obligatorios en el registro de cambio.'
          });
          continue;
        }

        // 1. Asignar tabla y esquema correspondientes
        let table: any;
        let schema: any;

        switch (entityType) {
          case 'clients':
            table = clients;
            schema = clientSyncSchema;
            break;
          case 'machines':
            table = machines;
            schema = machineSyncSchema;
            break;
          case 'readings':
            table = readings;
            schema = readingSyncSchema;
            break;
          case 'tickets':
            table = tickets;
            schema = ticketSyncSchema;
            break;
          case 'plans':
          case 'abonos':
            table = plans;
            schema = planSyncSchema;
            break;
          case 'users':
            table = users;
            schema = userSyncSchema;
            break;
          case 'rentals':
            table = rentals;
            schema = rentalSyncSchema;
            break;
          case 'budgets':
            table = budgets;
            schema = budgetSyncSchema;
            break;
          default:
            results.push({
              id,
              status: 'failed',
              reason: 'invalid_entity_type',
              message: `Tipo de entidad inv├ílido: ${entityType}`
            });
            continue;
        }

        // 2. Procesar operaci├│n de eliminaci├│n
        if (operation === 'delete') {
          try {
            await tx.delete(table).where(eq(table.id, entityId));
            results.push({ id, status: 'synced' });
          } catch (e: any) {
            console.error(`Error deleting entity ${entityType} ID ${entityId}:`, e);
            results.push({
              id,
              status: 'failed',
              reason: 'db_error',
              message: e.message
            });
          }
          continue;
        }

        // 3. Validar payload con Zod para operaciones de creaci├│n/actualizaci├│n
        const parsed = schema.safeParse(payload);
        if (!parsed.success) {
          console.error("!!! ZOD VALIDATION ERROR !!!", "Entity:", entityType, "ID:", entityId, "Error:", JSON.stringify(parsed.error.format(), null, 2));
          results.push({
            id,
            status: 'failed',
            reason: 'validation_error',
            details: parsed.error.format()
          });
          continue;
        }

        const cleanPayload = parsed.data;

        // Auto-reparar clientId y abonoId hu├®rfanos para lecturas
        if (entityType === 'readings') {
          const rPayload = cleanPayload as any;
          if (!rPayload.clientId || !rPayload.abonoId) {
            const mach = await tx.select().from(machines).where(eq(machines.id, rPayload.machineId)).limit(1);
            if (mach.length > 0) {
              rPayload.clientId = rPayload.clientId || mach[0].clientId;
              rPayload.abonoId = rPayload.abonoId || mach[0].abonoId;
            }
          }
        }

          // 4. Compare Last-Write-Wins (LWW) against database
          try {
            const existing = await tx.select().from(table).where(eq(table.id, entityId)).limit(1);

            // Always stamp with server time so incremental queries on other devices pick it up correctly.
            // Client clocks can drift ÔÇö server time is the authoritative timestamp for sync.
            const serverNow = new Date();
            const payloadWithServerTime = { ...cleanPayload, updatedAt: serverNow };

            if (existing.length > 0) {
              const dbItem: any = existing[0];
              const dbUpdatedAt = dbItem.updatedAt ? new Date(dbItem.updatedAt).getTime() : 0;
              const incomingUpdatedAt = new Date(cleanPayload.updatedAt || updatedAt).getTime();

              if (dbUpdatedAt > incomingUpdatedAt) {
                // El servidor tiene una versi├│n m├ís nueva. Omitimos escritura de forma exitosa.
                results.push({ id, status: 'synced', skipped: true, reason: 'server_has_newer_version' });
                continue;
              }

              // Actualizar registro existente con timestamp del servidor
              await tx.update(table).set(payloadWithServerTime).where(eq(table.id, entityId));
            } else {
              // Crear nuevo registro con timestamp del servidor
              await tx.insert(table).values(payloadWithServerTime);
            }
            results.push({ id, status: 'synced' });
          } catch (e: any) {
            console.error(`Error writing entity ${entityType} ID ${entityId}:`, e);
            results.push({
              id,
              status: 'failed',
              reason: 'db_error',
              message: e.message
            });
          }
      }
    });

    return NextResponse.json({ success: true, results });
  } catch (error: any) {
    console.error('Error en API de procesamiento de sincronizaci├│n:', error.message || error);
    return NextResponse.json({
      error: 'Error del servidor al procesar la cola de sincronizaci├│n.',
      code: 'SERVER_ERROR'
    }, { status: 500 });
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { sendTechNotification, NotificationEvent } from '@/infrastructure/notifications/notificationService';
import { autoAssignTech } from '@/domain/ticket/assignment';
import { Ticket, User } from '@/lib/mockData';

export async function POST(req: NextRequest) {
  try {
    const body = await req.json();
    const { tickets, users } = body as { tickets: Ticket[]; users: User[] };

    if (!tickets || !users) {
      return NextResponse.json({ error: 'Faltan par├ímetros (tickets, users).' }, { status: 400 });
    }

    const updatedTickets: Ticket[] = [];
    const executionLogs: string[] = [];

    const now = Date.now();

    for (const ticket of tickets) {
      // Omitir tickets concluidos o cerrados
      if (['resuelto', 'cerrado'].includes(ticket.status)) {
        updatedTickets.push(ticket);
        continue;
      }

      let ticketUpdated = false;
      const history = [...(ticket.history || [])];

      // A. Control de SLA (Alertas de vencimiento)
      if (ticket.slaDate) {
        const sla = new Date(ticket.slaDate);
        if (!isNaN(sla.getTime())) {
          const diffMs = sla.getTime() - now;
          const diffHours = diffMs / (1000 * 60 * 60);

          // 1. Alerta Cr├¡tica SLA Vencido
          if (diffMs < 0) {
            const alreadyNotifiedVencido = history.some(h => h.action.includes('Alerta cr├¡tica: El ticket ha vencido'));
            if (!alreadyNotifiedVencido) {
              const tech = users.find(u => u.id === ticket.assignedTechId);
              let logText = 'Alerta de SLA vencido registrada.';

              if (tech) {
                try {
                  const notifyResult = await sendTechNotification('sla_vencido', ticket, tech);
                  logText = `[Alerta SLA] Alerta cr├¡tica: El ticket ha vencido. ${notifyResult.logAction}`;
                } catch (e) {
                  logText = `[Alerta SLA] Alerta cr├¡tica: El ticket ha vencido. (WhatsApp/Email simulado)`;
                }
              } else {
                logText = `[Alerta SLA] Alerta cr├¡tica: El ticket ha vencido sin t├®cnico asignado.`;
              }

              history.push({
                date: new Date().toISOString().split('T')[0],
                time: new Date().toLocaleTimeString('es-AR').slice(0, 5),
                action: logText,
                user: 'Sistema'
              });
              ticketUpdated = true;
              executionLogs.push(`TCK-${ticket.id.replace('ticket-', '')}: Alerta de SLA vencido despachada.`);
            }
          }
          // 2. Recordatorio SLA por vencer (menor a 4 horas)
          else if (diffHours < 4) {
            const alreadyNotifiedPorVencer = history.some(h => h.action.includes('Recordatorio enviado: SLA por vencer'));
            if (!alreadyNotifiedPorVencer) {
              const tech = users.find(u => u.id === ticket.assignedTechId);
              let logText = 'Recordatorio de SLA por vencer registrado.';

              if (tech) {
                try {
                  const notifyResult = await sendTechNotification('sla_por_vencer', ticket, tech);
                  logText = `[Alerta SLA] Recordatorio enviado: SLA por vencer en menos de 4 horas. ${notifyResult.logAction}`;
                } catch (e) {
                  logText = `[Alerta SLA] Recordatorio enviado: SLA por vencer en menos de 4 horas.`;
                }
              }

              history.push({
                date: new Date().toISOString().split('T')[0],
                time: new Date().toLocaleTimeString('es-AR').slice(0, 5),
                action: logText,
                user: 'Sistema'
              });
              ticketUpdated = true;
              executionLogs.push(`TCK-${ticket.id.replace('ticket-', '')}: Recordatorio de SLA por vencer despachado.`);
            }
          }
        }
      }

      // B. Regla de Escalamiento por Inactividad (m├ís de 2 horas sin actualizaciones)
      const ticketCreatedTime = ticket.createdAt || (new Date(ticket.date + 'T' + ticket.time).getTime());

      // Obtener el timestamp de la ├║ltima actividad del historial
      let lastActivityTime = ticketCreatedTime;
      if (history.length > 0) {
        const lastH = history[history.length - 1];
        const lastHTime = new Date(lastH.date + 'T' + lastH.time).getTime();
        if (!isNaN(lastHTime)) {
          lastActivityTime = lastHTime;
        }
      }

      const inactivityMs = now - lastActivityTime;
      const inactivityHours = inactivityMs / (1000 * 60 * 60);

      // Si lleva m├ís de 2 horas inactivo en estado nuevo o asignado
      if (['nuevo', 'asignado'].includes(ticket.status) && inactivityHours >= 2) {
        const alreadyEscalated = history.some(h => h.action.includes('Escalamiento Autom├ítico'));

        if (!alreadyEscalated) {
          // 1. Elevar prioridad a urgente
          const prevPriority = ticket.priority;
          const newPriority = 'urgente';

          // 2. Recalcular SLA a 4 horas cr├¡ticas
          const newSla = new Date();
          newSla.setHours(newSla.getHours() + 4);

          // 3. Ejecutar autoasignaci├│n inteligente
          const activeTicketsList = tickets.filter(t => t.id !== ticket.id);
          const assignResult = autoAssignTech(ticket, users, activeTicketsList);

          let escalationLog = `[Escalamiento Autom├ítico] Prioridad elevada de ${prevPriority.toUpperCase()} a URGENTE y SLA recalculado a 4 horas por inactividad (>2h).`;

          const assignedTech = users.find(u => u.id === assignResult.techId);
          let newStatus = ticket.status;

          if (assignedTech) {
            newStatus = 'asignado';
            escalationLog += ` Reasignado autom├íticamente al t├®cnico disponible: ${assignedTech.fullname} (Score: ${assignResult.score}).`;
          } else {
            escalationLog += ` No se encontraron t├®cnicos disponibles para reasignaci├│n.`;
          }

          history.push({
            date: new Date().toISOString().split('T')[0],
            time: new Date().toLocaleTimeString('es-AR').slice(0, 5),
            action: escalationLog,
            user: 'Sistema'
          });

          const escalatedTicket: Ticket = {
            ...ticket,
            priority: newPriority,
            status: newStatus,
            assignedTechId: assignResult.techId || ticket.assignedTechId,
            slaDate: newSla.toISOString(),
            history
          };

          // Intentar notificar al nuevo t├®cnico asignado
          if (assignedTech) {
            try {
              const notifyResult = await sendTechNotification('reasignado', escalatedTicket, assignedTech);
              history.push({
                date: new Date().toISOString().split('T')[0],
                time: new Date().toLocaleTimeString('es-AR').slice(0, 5),
                action: `[Notificaci├│n Escalamiento] ${notifyResult.logAction}`,
                user: 'Sistema'
              });
            } catch (err) {
              // ignore
            }
          }

          updatedTickets.push(escalatedTicket);
          executionLogs.push(`TCK-${ticket.id.replace('ticket-', '')}: Ticket escalado por inactividad.`);
          continue;
        }
      }

      if (ticketUpdated) {
        updatedTickets.push({
          ...ticket,
          history
        });
      } else {
        updatedTickets.push(ticket);
      }
    }

    return NextResponse.json({
      success: true,
      tickets: updatedTickets,
      logs: executionLogs
    });
  } catch (error: any) {
    console.error('Error in tickets cron route:', error);
    return NextResponse.json({ error: 'Server error processing tickets cron.' }, { status: 500 });
  }
}

