source:
'use client';

import React, { useEffect, useState, useRef } from 'react';
import { CheckCircle, XCircle, RefreshCw, WifiOff, X } from 'lucide-react';

export type ToastType = 'success' | 'error' | 'syncing' | 'offline';

export interface ToastMessage {
    id: string;
    type: ToastType;
    title: string;
    detail?: string;
    duration?: number;
}

interface ToastItemProps {
    toast: ToastMessage;
    onDismiss: (id: string) => void;
}

const COLORS: Record<ToastType, { bg: string; border: string; icon: string; title: string }> = {
    success: { bg: 'rgba(16,185,129,0.13)', border: 'rgba(16,185,129,0.5)', icon: '#10b981', title: '#d1fae5' },
    error:   { bg: 'rgba(239,68,68,0.13)',  border: 'rgba(239,68,68,0.5)',  icon: '#ef4444', title: '#fee2e2' },
    syncing: { bg: 'rgba(99,102,241,0.13)', border: 'rgba(99,102,241,0.4)', icon: '#818cf8', title: '#e0e7ff' },
    offline: { bg: 'rgba(234,179,8,0.13)',  border: 'rgba(234,179,8,0.45)', icon: '#eab308', title: '#fef9c3' },
};

function ToastItem({ toast, onDismiss }: ToastItemProps) {
    const [visible, setVisible] = useState(false);
    const timerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
    const colors = COLORS[toast.type];

    useEffect(() => {
        const enterTimer = setTimeout(() => setVisible(true), 10);
        const duration = toast.duration ?? (toast.type === 'syncing' ? 3000 : toast.type === 'error' ? 6000 : 4000);
        if (duration > 0) {
            timerRef.current = setTimeout(() => {
                setVisible(false);
                setTimeout(() => onDismiss(toast.id), 350);
            }, duration);
        }
        return () => {
            clearTimeout(enterTimer);
            if (timerRef.current) clearTimeout(timerRef.current);
        };
    }, [toast.id, toast.type, toast.duration, onDismiss]);

    const Icon = () => {
        if (toast.type === 'success') return <CheckCircle size={18} />;
        if (toast.type === 'error')   return <XCircle size={18} />;
        if (toast.type === 'offline') return <WifiOff size={18} />;
        return <RefreshCw size={16} style={{ animation: 'toast-spin 1s linear infinite' }} />;
    };

    return (
        <div
            role="status"
            aria-live="polite"
            style={{
                display: 'flex', alignItems: 'flex-start', gap: '10px',
                padding: '12px 14px', borderRadius: '10px',
                background: colors.bg, border: `1px solid ${colors.border}`,
                backdropFilter: 'blur(12px)',
                boxShadow: '0 4px 24px rgba(0,0,0,0.35)',
                minWidth: '280px', maxWidth: '360px',
                transform: visible ? 'translateX(0) scale(1)' : 'translateX(110%) scale(0.95)',
                opacity: visible ? 1 : 0,
                transition: 'transform 0.32s cubic-bezier(0.34,1.56,0.64,1), opacity 0.3s ease',
            }}
        >
            <span style={{ color: colors.icon, flexShrink: 0, marginTop: '1px' }}><Icon /></span>
            <div style={{ flex: 1, minWidth: 0 }}>
                <p style={{ margin: 0, fontWeight: 600, fontSize: '13px', color: colors.title, lineHeight: '1.35' }}>
                    {toast.title}
                </p>
                {toast.detail && (
                    <p style={{ margin: '3px 0 0', fontSize: '11.5px', color: 'rgba(255,255,255,0.55)', lineHeight: '1.4', wordBreak: 'break-word' }}>
                        {toast.detail}
                    </p>
                )}
            </div>
            <button
                aria-label="Cerrar"
                onClick={() => { setVisible(false); setTimeout(() => onDismiss(toast.id), 350); }}
                style={{ background: 'none', border: 'none', cursor: 'pointer', color: 'rgba(255,255,255,0.4)', padding: 0, flexShrink: 0 }}
            >
                <X size={13} />
            </button>
        </div>
    );
}

let _setGlobalToasts: React.Dispatch<React.SetStateAction<ToastMessage[]>> | null = null;

export function showToast(msg: Omit<ToastMessage, 'id'>) {
    if (!_setGlobalToasts) return;
    const id = 'toast-' + Date.now() + '-' + Math.random().toString(36).substring(2, 6);
    _setGlobalToasts(prev => [...prev.slice(-4), { ...msg, id }]);
}

export function showSaveSuccess(detail?: string) {
    showToast({ type: 'success', title: 'Guardado en la base de datos', detail });
}

export function showSaveError(detail?: string) {
    showToast({ type: 'error', title: 'Error al guardar', detail: detail || 'No se pudo sincronizar el cambio.' });
}

export function showOffline() {
    showToast({ type: 'offline', title: 'Sin conexion', detail: 'Los cambios se guardaran cuando vuelva la conexion.' });
}

export function ToastContainer() {
    const [toasts, setToasts] = useState<ToastMessage[]>([]);

    useEffect(() => {
        _setGlobalToasts = setToasts;
        return () => { _setGlobalToasts = null; };
    }, []);

    const dismiss = React.useCallback((id: string) => {
        setToasts(prev => prev.filter(t => t.id !== id));
    }, []);

    if (toasts.length === 0) return null;

    return (
        <>
            <style>{`
                @keyframes toast-spin { from { transform: rotate(0deg); } to { transform: rotate(360deg); } }
            `}</style>
            <div
                aria-label="Notificaciones"
                style={{
                    position: 'fixed', bottom: '20px', right: '20px',
                    zIndex: 99999, display: 'flex', flexDirection: 'column',
                    gap: '10px', alignItems: 'flex-end', pointerEvents: 'none',
                }}
            >
                {toasts.map(t => (
                    <div key={t.id} style={{ pointerEvents: 'all' }}>
                        <ToastItem toast={t} onDismiss={dismiss} />
                    </div>
                ))}
            </div>
        </>
    );
}

import { cookies, headers } from 'next/headers';
import { db } from '@/infrastructure/db/client';
import { sessions } from '@/infrastructure/db/schema/sessions';
import { users } from '@/infrastructure/db/schema/users';
import { eq, and, isNull } from 'drizzle-orm';

import { UserSession, decryptSession, encryptSession, isMasterUser } from '@/lib/auth/sessionDecrypt';

const SESSION_COOKIE_NAME = 'ms_session';
const SESSION_DURATION_DAYS = 14;
const SESSION_DURATION_MS = SESSION_DURATION_DAYS * 24 * 60 * 60 * 1000;
const SESSION_RENEWAL_MS = 7 * 24 * 60 * 60 * 1000; // Renew if less than 7 days left

function generateSessionId(): string {
  const bytes = crypto.getRandomValues(new Uint8Array(20));
  return Array.from(bytes).map(b => b.toString(16).padStart(2, '0')).join('');
}

/**
 * Crea una sesi├│n en base de datos y genera una cookie encriptada.
 */
export async function createSession(
  user: { id: string; username: string; fullname: string; role: string; isMaster?: boolean },
  ip: string = '',
  userAgent: string = ''
) {
  const sessionId = generateSessionId();
  const expiresAt = new Date(Date.now() + SESSION_DURATION_MS); // 14 d├¡as en base de datos

  // 1. Persistir en la base de datos Turso
  await db.insert(sessions).values({
    id: sessionId,
    userId: user.id,
    expiresAt,
    lastSeenAt: new Date(),
    ip: ip || null,
    userAgent: userAgent || null,
  });

  const sessionPayload: UserSession = {
    userId: user.id,
    username: user.username,
    fullname: user.fullname,
    role: user.role,
    isMaster: isMasterUser(user),
    sessionId,
    expiresAt: expiresAt.getTime(),
  };

  // 2. Encriptar sesi├│n y escribir cookie
  const encrypted = await encryptSession(sessionPayload);
  const cookieStore = await cookies();

  let isSecure = false;
  try {
    const headersList = await headers();
    const proto = headersList.get('x-forwarded-proto') || '';
    const host = headersList.get('host') || '';
    isSecure = proto === 'https' || (host.includes('localhost') === false && process.env.NODE_ENV === 'production');
  } catch (e) {
    isSecure = process.env.NODE_ENV === 'production';
  }

  cookieStore.set(SESSION_COOKIE_NAME, encrypted, {
    httpOnly: true,
    secure: isSecure,
    sameSite: 'lax',
    path: '/',
    maxAge: SESSION_DURATION_DAYS * 24 * 60 * 60, // 14 d├¡as
  });

  return sessionId;
}

/**
 * Recupera, desencripta y valida la sesi├│n contra la base de datos.
 * Implementa renovaci├│n autom├ítica ("sliding expiration") cuando queda menos de la mitad del tiempo.
 */
export async function getSession(requestOrCookieValue?: Request | string): Promise<UserSession | null> {
  let token: string | undefined;

  if (requestOrCookieValue && typeof requestOrCookieValue !== 'string') {
    const cookieHeader = requestOrCookieValue.headers.get('cookie') || '';
    const sessionCookieValue = cookieHeader
      .split(';')
      .find(c => c.trim().startsWith(`${SESSION_COOKIE_NAME}=`))
      ?.split('=')[1];
    token = sessionCookieValue ? decodeURIComponent(sessionCookieValue) : undefined;
  } else if (typeof requestOrCookieValue === 'string') {
    token = requestOrCookieValue;
  }

  if (!token) {
    const cookieStore = await cookies();
    const sessionCookie = cookieStore.get(SESSION_COOKIE_NAME);
    if (!sessionCookie) return null;
    token = sessionCookie.value;
  }

  const isCustomToken = !!requestOrCookieValue;

  // 1. Desencriptar cookie
  const session = await decryptSession(token);
  if (!session) {
    try {
      await deleteSession();
    } catch (e) {}
    return null;
  }

  // 2. Validar expiraci├│n del payload (como redundancia offline con margen de gracia de 5 minutos para skew de reloj)
  const CLOCK_SKEW_MS = 5 * 60 * 1000; // 5 minutes
  if (Date.now() > session.expiresAt + CLOCK_SKEW_MS) {
    try {
      await deleteSession();
    } catch (e) {}
    return null;
  }

  try {
    // 3. Validar estado en la base de datos (revocaciones e inactividad)
    const results = await db
      .select({
        dbSession: sessions,
        dbUser: users,
      })
      .from(sessions)
      .innerJoin(users, eq(sessions.userId, users.id))
      .where(
        and(
          eq(sessions.id, session.sessionId),
          isNull(sessions.revokedAt),
          eq(users.active, 1)
        )
      )
      .limit(1);

    const match = results[0];
    if (!match) {
      try {
        await deleteSession();
      } catch (e) {}
      return null;
    }

    // 3b. Validar expiraci├│n real de la base de datos (fuente de verdad definitiva)
    const dbExpiresAtMs = new Date(match.dbSession.expiresAt).getTime();
    if (Date.now() > dbExpiresAtMs) {
      try {
        await deleteSession();
      } catch (e) {}
      return null;
    }

    // 4. Sliding Expiration (Renovaci├│n autom├ítica) si queda menos de la mitad del tiempo (7 d├¡as)
    const now = Date.now();
    const remainingTime = dbExpiresAtMs - now;

    if (remainingTime < SESSION_RENEWAL_MS) {
      const newExpiresAt = new Date(now + SESSION_DURATION_MS);

      // Actualizar en base de datos
      db.update(sessions)
        .set({ expiresAt: newExpiresAt, lastSeenAt: new Date() })
        .where(eq(sessions.id, session.sessionId))
        .catch(err => console.error('Error al renovar expiraci├│n de sesi├│n en BD:', err));

      // Re-generar cookie con nueva expiraci├│n
      const updatedPayload: UserSession = {
        ...session,
        role: match.dbUser.role,
        isMaster: isMasterUser(match.dbUser),
        expiresAt: newExpiresAt.getTime(),
      };

      try {
        const encrypted = await encryptSession(updatedPayload);
        const cookieStore = await cookies();

        let isSecure = false;
        try {
          const headersList = await headers();
          const proto = headersList.get('x-forwarded-proto') || '';
          const host = headersList.get('host') || '';
          isSecure = proto === 'https' || (host.includes('localhost') === false && process.env.NODE_ENV === 'production');
        } catch (e) {
          isSecure = process.env.NODE_ENV === 'production';
        }

        cookieStore.set(SESSION_COOKIE_NAME, encrypted, {
          httpOnly: true,
          secure: isSecure,
          sameSite: 'lax',
          path: '/',
          maxAge: SESSION_DURATION_DAYS * 24 * 60 * 60,
        });
      } catch (cookieErr) {
        console.error('Error al renovar cookie de sesi├│n (puede no estar en request context):', cookieErr);
      }

      return {
        ...session,
        role: match.dbUser.role,
        isMaster: isMasterUser(match.dbUser),
        expiresAt: newExpiresAt.getTime(),
      };
    } else {
      // Solo actualizar lastSeenAt
      db.update(sessions)
        .set({ lastSeenAt: new Date() })
        .where(eq(sessions.id, session.sessionId))
        .catch(err => console.error('Error al actualizar lastSeenAt:', err));

      return {
        ...session,
        role: match.dbUser.role,
        isMaster: isMasterUser(match.dbUser),
      };
    }
  } catch (error) {
    console.error('Error en base de datos al validar sesi├│n:', error);
    // Si la base de datos no est├í disponible, mantener offline-fallback de la cookie encriptada
    return session;
  }
}

/**
 * Revoca la sesi├│n en la base de datos y borra la cookie.
 */
export async function deleteSession() {
  const cookieStore = await cookies();
  const sessionCookie = cookieStore.get(SESSION_COOKIE_NAME);

  if (sessionCookie) {
    const session = await decryptSession(sessionCookie.value);
    if (session) {
      try {
        await db
          .update(sessions)
          .set({ revokedAt: new Date() })
          .where(eq(sessions.id, session.sessionId));
      } catch (e) {
        console.error('Error al revocar sesi├│n en BD:', e);
      }
    }
  }

  cookieStore.delete(SESSION_COOKIE_NAME);
}

/**
 * Revoca todas las sesiones activas de un usuario.
 */
export async function revokeAllSessionsForUser(userId: string) {
  try {
    await db
      .update(sessions)
      .set({ revokedAt: new Date() })
      .where(and(eq(sessions.userId, userId), isNull(sessions.revokedAt)));
  } catch (e) {
    console.error('Error al revocar todas las sesiones del usuario:', e);
  }
}

import { drizzle } from 'drizzle-orm/libsql';
import { createClient } from '@libsql/client';
import * as schema from './schema';

// Singleton pattern para evitar m├║ltiples conexiones en entornos serverless
let _db: ReturnType<typeof drizzle> | null = null;

function getDb() {
  if (_db) return _db;

  const url = process.env.DATABASE_URL || process.env.TURSO_DATABASE_URL;
  const authToken = process.env.DATABASE_AUTH_TOKEN || process.env.TURSO_AUTH_TOKEN;

  if (!url || url === 'file:local.db') {
    throw new Error('DATABASE_URL no est├í configurada. Verificar variables de entorno en Netlify.');
  }

  const client = createClient({ url, authToken });
  _db = drizzle(client, { schema });
  return _db;
}

export const db = new Proxy({} as ReturnType<typeof drizzle>, {
  get(_, prop) {
    return (getDb() as any)[prop];
  }
});

